INSERT INTO kb.Tag (id_category, name, synonyms, definition)
SELECT c.id_category, v.name, v.synonyms, v.definition
FROM (VALUES
    (N'Строительный материал', N'Материалы', N'стройматериал; стройматериалы', N'Материал или изделие, применяемое для возведения и ремонта зданий и сооружений.'),
    (N'Стеновой материал', N'Материалы', N'материал для стен; стеновые блоки', N'Материалы для кладки несущих и ограждающих стен: кирпич, блоки, камни.'),
    (N'Кирпич', N'Материалы', N'кирпичи', N'Штучный стеновой материал правильной формы стандартного размера 250×120×65 мм.'),
    (N'Керамический кирпич', N'Материалы', N'красный кирпич; глиняный кирпич; керамика стеновая', N'Кирпич из обожжённой глины. Прочный, морозостойкий, пригоден для несущих стен и цоколя.'),
    (N'Силикатный кирпич', N'Материалы', N'белый кирпич; известково-песчаный кирпич', N'Кирпич автоклавного твердения из извести и кварцевого песка; тяжёлый и звукоизолирующий, но боится постоянной влаги.'),
    (N'Облицовочный кирпич', N'Материалы', N'лицевой кирпич; фасадный кирпич', N'Кирпич с ровной декоративной поверхностью для наружного слоя кладки.'),
    (N'Ячеистый бетон', N'Материалы', N'ячеистые бетоны; пористый бетон', N'Лёгкий бетон с равномерно распределёнными порами; объединяет газобетон и пенобетон.'),
    (N'Газобетон', N'Материалы', N'газоблок; газосиликат; газобетонный блок; автоклавный газобетон; газосиликатный блок', N'Автоклавный ячеистый бетон, поры которого образуются при реакции алюминиевой пудры с известью. Лёгкий и тёплый стеновой материал.'),
    (N'Пенобетон', N'Материалы', N'пеноблок; пенобетонный блок', N'Ячеистый бетон, поры которого созданы пенообразователем; чаще неавтоклавный.'),
    (N'Керамический блок', N'Материалы', N'поризованный блок; тёплая керамика; керамоблок; крупноформатный керамический камень', N'Крупноформатный пустотелый камень из поризованной керамики для однослойных тёплых стен.'),
    (N'Бетон', N'Материалы', N'бетонная смесь; товарный бетон', N'Искусственный камень из цемента, воды, песка и щебня. Класс по прочности обозначают B.'),
    (N'Железобетон', N'Материалы', N'ЖБИ; армированный бетон; железобетонные изделия', N'Бетон, усиленный стальной арматурой, которая воспринимает растягивающие нагрузки.'),
    (N'Цемент', N'Материалы', N'портландцемент; ПЦ', N'Гидравлическое вяжущее, твердеющее при смешивании с водой. Основа бетонов и растворов.'),
    (N'Строительный раствор', N'Материалы', N'кладочный раствор; цементно-песчаный раствор; ЦПС', N'Смесь вяжущего, песка и воды для кладки и штукатурных работ.'),
    (N'Сухая строительная смесь', N'Материалы', N'сухая смесь; ССС', N'Заводская смесь вяжущего, заполнителя и добавок, затворяемая водой на объекте.'),
    (N'Штукатурка', N'Материалы', N'штукатурная смесь; штукатурный раствор; цементная штукатурка', N'Смесь для выравнивания стен и потолков слоем 5–50 мм.'),
    (N'Гипсовая штукатурка', N'Материалы', N'гипсовая смесь', N'Штукатурка на гипсовом вяжущем для сухих помещений: быстро схватывается, не требует шпатлёвки.'),
    (N'Шпатлёвка', N'Материалы', N'шпаклёвка; шпаклевка; шпатлевка', N'Тонкослойная смесь для финишного выравнивания поверхности под покраску или обои.'),
    (N'Плиточный клей', N'Материалы', N'клей для плитки', N'Цементная сухая смесь для приклеивания керамической плитки и керамогранита.'),
    (N'Гипсокартон', N'Материалы', N'ГКЛ; гипсокартонный лист; сухая штукатурка; гипсовая плита', N'Лист из гипсового сердечника, облицованного картоном. Для перегородок, облицовки и потолков.'),
    (N'Влагостойкий гипсокартон', N'Материалы', N'ГКЛВ; зелёный гипсокартон', N'Гипсокартон с гидрофобными добавками и зелёным картоном для влажных помещений.'),
    (N'Огнестойкий гипсокартон', N'Материалы', N'ГКЛО; гипсокартон огнестойкий', N'Гипсокартон, армированный стекловолокном; дольше сохраняет целостность при пожаре.'),
