INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Керамический кирпич: свойства, марки и применение', N'Из чего делают керамический кирпич, какие бывают марки прочности и морозостойкости и где его применяют.', N'Керамический кирпич изготавливают из глины с добавками, формуют и обжигают при температуре 950–1050 °C. После обжига материал приобретает высокую прочность и стойкость к воде и морозу.

Прочность обозначается маркой М: М100, М125, М150, М175, М200. Цифра показывает нагрузку в кгс/см², которую выдерживает кирпич. Для стен частного дома в 2–3 этажа достаточно марки М100–М150, для цоколя и фундамента выбирают М150–М200.

Морозостойкость обозначают маркой F: F25, F35, F50, F75, F100. Для облицовки и цоколя рекомендуется не ниже F50.

Средняя плотность полнотелого кирпича 1600–1900 кг/м³, теплопроводность 0,5–0,8 Вт/(м·К). Пустотелый кирпич легче и теплее: теплопроводность 0,3–0,5 Вт/(м·К).

Керамический кирпич не горит, служит более 100 лет и пригоден для несущих наружных стен, перегородок, цоколя, печей (только специальный огнеупорный) и фундаментов. Требования к нему устанавливают ГОСТ 530-2012 и СТБ 1160-99.', '2025-02-10', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Керамический кирпич', 1.0), (N'Прочность на сжатие', 0.6), (N'Морозостойкость', 0.6), (N'Наружные стены', 0.5), (N'ГОСТ 530-2012', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Керамический кирпич: свойства, марки и применение';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Силикатный кирпич: плюсы, минусы и ограничения', N'Белый кирпич из извести и песка: где его можно применять, а где нельзя.', N'Силикатный кирпич производят из кварцевого песка (около 90 %) и извести (около 10 %) методом автоклавного твердения: смесь прессуют и выдерживают паром под давлением при температуре 170–200 °C.

Плотность силикатного кирпича 1800–1950 кг/м³, теплопроводность 0,7–0,9 Вт/(м·К), поэтому стены из него холоднее, чем из керамики, и требуют утепления. Зато массивная кладка хорошо гасит шум: силикатный кирпич отлично подходит для межквартирных стен и перегородок.

Главный недостаток — повышенное водопоглощение (8–16 %) и меньшая стойкость к постоянному увлажнению. Силикатный кирпич нельзя применять для фундаментов, цоколя, подвалов, печей и дымоходов.

Марки прочности М75–М300, морозостойкость F25–F50. Требования устанавливает ГОСТ 379-2015. Силикатный кирпич обычно дешевле керамического и обладает точной геометрией, поэтому его часто выбирают для лицевой кладки многоэтажных домов.', '2025-02-14', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Силикатный кирпич', 1.0), (N'Звукоизоляция', 0.6), (N'Водопоглощение', 0.5), (N'ГОСТ 379-2015', 0.4), (N'Перегородки', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Силикатный кирпич: плюсы, минусы и ограничения';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Газобетон: тёплая стена без утеплителя?', N'Марки плотности D300–D600, теплопроводность и прочность газобетонных блоков.', N'Газобетон (газосиликатный блок) — автоклавный ячеистый бетон. В смесь цемента, извести, песка и воды добавляют алюминиевую пудру; при реакции выделяется водород, и масса вспучивается. Затем блоки твердеют в автоклаве.

Марка по плотности D показывает массу кубометра в килограммах: D300, D400, D500, D600. Чем ниже плотность, тем теплее блок, но ниже прочность. Для несущих стен частного дома обычно берут D400–D500 класса прочности B2,5–B3,5.

Теплопроводность газобетона D500 в сухом состоянии около 0,12 Вт/(м·К) — в 4–5 раз меньше, чем у керамического кирпича. Стена из блока D400 толщиной 400 мм может соответствовать нормам теплозащиты без дополнительного утепления.

Газобетон негорюч, паропроницаем и легко обрабатывается: его пилят ножовкой. Блоки кладут на тонкослойный клей толщиной 2–3 мм, что уменьшает мостики холода. Недостатки — хрупкость при изгибе, необходимость армирования кладки и защиты фасада от влаги. Требования установлены ГОСТ 31360-2007.', '2025-03-01', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Газобетон', 1.0), (N'Теплопроводность', 0.8), (N'Плотность', 0.6), (N'Наружные стены', 0.6), (N'ГОСТ 31360-2007', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Газобетон: тёплая стена без утеплителя?';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Газобетон или пенобетон: что выбрать', N'Сравнение двух видов ячеистого бетона по прочности, геометрии и стабильности качества.', N'Газобетон и пенобетон относятся к ячеистым бетонам, но производятся по-разному. Поры газобетона образуются химической реакцией, а пенобетона — пенообразователем, который вводят в раствор.

Газобетон почти всегда автоклавный и выпускается на крупных заводах, поэтому у него стабильная плотность и точная геометрия (отклонения до 1–2 мм). Пенобетон часто делают неавтоклавным, на небольших производствах: его прочность ниже, усадка выше, а размеры блоков менее точные.

Пенобетон с закрытыми порами меньше впитывает воду, но при одинаковой плотности прочнее газобетон. Для несущих стен надёжнее газобетон, а пенобетон оправдан для перегородок и утепления.

Если нужно заменить газобетон на пенобетон, выбирайте блоки на 100 единиц плотности выше (D600 вместо D500), чтобы сохранить прочность, и учитывайте, что стена станет немного холоднее.', '2025-03-05', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Сравнение' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Газобетон', 0.9), (N'Пенобетон', 0.9), (N'Ячеистый бетон', 0.7)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Газобетон или пенобетон: что выбрать';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Керамический блок (тёплая керамика)', N'Крупноформатные поризованные камни для однослойных стен.', N'Керамический блок — крупноформатный камень из глины с добавлением опилок или торфа, которые выгорают при обжиге и образуют микропоры. Внутри блок имеет множество вертикальных пустот.

Один блок 380×250×219 мм заменяет около 15 обычных кирпичей, поэтому стены возводятся в 3–4 раза быстрее. Теплопроводность кладки 0,14–0,2 Вт/(м·К), прочность М75–М150.

В Германии и Австрии такие блоки — самый распространённый материал для частных домов. Они сочетают долговечность керамики (100 лет и более) с хорошей теплоизоляцией и паропроницаемостью.

Недостатки: хрупкость при резке и сверлении, необходимость специальных дюбелей для навесного оборудования, цена выше газобетона. Кладку ведут на тёплый раствор, чтобы швы не стали мостиками холода. Блоки соответствуют ГОСТ 530-2012.', '2025-01-20', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Обзор европейской практики' AND ct.name = N'Справочная статья' AND c.name = N'Германия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Керамический блок', 1.0), (N'Теплопроводность', 0.6), (N'Наружные стены', 0.6), (N'Керамический кирпич', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Керамический блок (тёплая керамика)';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Цемент М500 Д0 и новая маркировка ЦЕМ', N'Как читать маркировку цемента и какой цемент выбрать для фундамента, стяжки и кладки.', N'Цемент получают помолом клинкера с гипсом (3–5 %) и минеральными добавками. Клинкер образуется при обжиге смеси известняка и глины при 1450 °C.

По старой маркировке «М500 Д0» означает: марка прочности 500 кгс/см², Д0 — без минеральных добавок. «Д20» содержит до 20 % добавок, он дешевле и медленнее набирает прочность.

По ГОСТ 31108-2020 используется европейская маркировка: ЦЕМ I 42,5Н. ЦЕМ I — портландцемент без добавок, ЦЕМ II — с добавками; 42,5 — класс прочности в МПа; Н — нормальнотвердеющий, Б — быстротвердеющий.

Для фундамента и ответственных бетонов применяют М500 (ЦЕМ I 42,5), для кладочных и штукатурных растворов достаточно М400 (ЦЕМ II 32,5). Срок хранения цемента в мешках — до 6 месяцев: со временем он теряет до 20 % активности, особенно во влажном складе.', '2024-11-12', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Технический бюллетень производителей' AND ct.name = N'Справочная статья' AND c.name = N'Россия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Цемент', 1.0), (N'ГОСТ 31108-2020', 0.7), (N'Прочность на сжатие', 0.5), (N'Клинкер', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Цемент М500 Д0 и новая маркировка ЦЕМ';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Класс бетона и марка: как выбрать бетон для фундамента', N'Какой бетон заказать для ленточного фундамента частного дома.', N'Прочность бетона обозначают классом B (гарантированная прочность в МПа) или маркой М (средняя прочность в кгс/см²). Соответствие: B15 ≈ М200, B20 ≈ М250, B22,5 ≈ М300, B25 ≈ М350, B30 ≈ М400.

Для ленточного фундамента частного дома из газобетона или каркаса достаточно бетона B20 (М250). Для кирпичного дома в 2–3 этажа и плитного фундамента выбирают B22,5–B25 (М300–М350).

Кроме прочности важны морозостойкость F (для фундамента — не ниже F150), водонепроницаемость W (не ниже W4–W6) и подвижность смеси П (для заливки в опалубку с арматурой — П3–П4).

Бетонная смесь должна соответствовать ГОСТ 7473-2010. Залитый бетон набирает 70 % прочности примерно за 7 суток и проектную прочность за 28 суток при температуре около 20 °C. Первые дни бетон нужно поливать водой и укрывать от солнца.', '2025-04-02', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Бетон', 1.0), (N'Фундамент', 0.8), (N'Прочность на сжатие', 0.6), (N'Морозостойкость', 0.4), (N'ГОСТ 7473-2010', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Класс бетона и марка: как выбрать бетон для фундамента';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Железобетон и армирование фундамента', N'Почему бетон армируют и как устроен арматурный каркас ленточного фундамента.', N'Бетон хорошо работает на сжатие, но плохо на растяжение: его прочность при растяжении примерно в 10 раз ниже. Стальная арматура воспринимает растягивающие усилия, а бетон защищает её от коррозии. Так получается железобетон.

Для ленточного фундамента применяют рабочую арматуру периодического профиля диаметром 10–14 мм класса А500С (А-III). Каркас вяжут из двух сеток: по 2–3 стержня сверху и снизу ленты. Поперечные хомуты делают из гладкой арматуры 6–8 мм с шагом 300–400 мм.

Защитный слой бетона — расстояние от арматуры до поверхности — должен быть не менее 40 мм, иначе сталь начнёт ржаветь. Для этого каркас ставят на пластиковые фиксаторы.

Стержни соединяют вязальной проволокой с нахлёстом не менее 30–40 диаметров. Сварка допускается только для свариваемых марок стали с индексом «С».', '2025-04-10', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Железобетон', 1.0), (N'Арматура', 0.8), (N'Армирование', 0.8), (N'Фундамент', 0.6)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Железобетон и армирование фундамента';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Гипсокартон: виды ГКЛ, ГКЛВ, ГКЛО', N'Как отличить виды гипсокартона по цвету и маркировке и где их применять.', N'Гипсокартонный лист состоит из гипсового сердечника, облицованного с двух сторон картоном. Стандартные размеры: ширина 1200 мм, длина 2500–3000 мм, толщина 12,5 мм для стен и 9,5 мм для потолков.

ГКЛ — обычный лист: серый картон, синяя маркировка. Применяется в сухих помещениях для перегородок, облицовки стен и потолков.

ГКЛВ — влагостойкий лист: зелёный картон, синяя маркировка. Содержит гидрофобные и противогрибковые добавки. Подходит для ванных комнат, кухонь и санузлов, но при условии гидроизоляции и вентиляции.

ГКЛО — огнестойкий лист: серый картон, красная маркировка. Сердечник армирован стекловолокном, поэтому лист дольше сохраняет целостность при пожаре. Применяется для облицовки воздуховодов, шахт и в помещениях с повышенными требованиями пожарной безопасности. ГКЛВО сочетает оба свойства.

Требования к листам установлены ГОСТ 32614-2012. Гипсокартонная перегородка с минеральной ватой внутри обеспечивает хорошую звукоизоляцию при малом весе.', '2025-02-20', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Гипсокартон', 1.0), (N'Влагостойкий гипсокартон', 0.8), (N'Огнестойкий гипсокартон', 0.8), (N'ГОСТ 32614-2012', 0.4), (N'Перегородки', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Гипсокартон: виды ГКЛ, ГКЛВ, ГКЛО';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Перегородка из гипсокартона своими руками', N'Пошаговая технология монтажа каркасной перегородки.', N'1. Разметьте положение перегородки на полу, перенесите линию на потолок с помощью отвеса или лазерного уровня.

2. Закрепите направляющие профили ПН 50×40 или 75×40 к полу и потолку дюбелями с шагом 500–600 мм. Под профиль проклейте уплотнительную ленту — она снижает передачу звука.

3. Установите стоечные профили ПС с шагом 600 мм (под ширину листа 1200 мм). В дверном проёме стойки усиливают деревянным брусом.

4. Обшейте каркас гипсокартоном с одной стороны саморезами 3,5×25 с шагом 250 мм. Шляпки утапливают на 1 мм.

5. Проложите внутри плиты минеральной ваты толщиной 50 мм для звукоизоляции и электропроводку в гофре.

6. Обшейте вторую сторону. Стыки листов на разных сторонах смещайте на одну стойку.

7. Заделайте швы шпатлёвкой с армирующей лентой, затем прошпатлюйте поверхность целиком.

Во влажных помещениях используйте влагостойкий гипсокартон ГКЛВ.', '2025-05-05', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Гипсокартон', 0.9), (N'Перегородки', 0.9), (N'Минеральная вата', 0.5), (N'Звукоизоляция', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Перегородка из гипсокартона своими руками';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Минеральная вата: каменная (базальтовая) теплоизоляция', N'Свойства, плотность и области применения каменной ваты.', N'Каменную (базальтовую) минеральную вату получают из расплава горных пород габбро-базальтовой группы при температуре около 1500 °C. Расплав раздувают в тонкие волокна, которые скрепляют связующим и формуют плиты.

Теплопроводность минеральной ваты 0,035–0,045 Вт/(м·К). Материал негорюч (группа НГ), волокна выдерживают температуру до 1000 °C, поэтому минвату применяют там, где важна пожарная безопасность: в фасадах, банях, перекрытиях, вокруг дымоходов.

Плотность плит выбирают по нагрузке: 30–45 кг/м³ — для скатной кровли и каркасных стен, 80–100 кг/м³ — для вентилируемых фасадов, 125–150 кг/м³ — для штукатурного (мокрого) фасада и плоской кровли.

Минеральная вата паропроницаема и хорошо поглощает звук. Главный враг — влага: намокшая вата теряет теплоизоляционные свойства, поэтому её защищают пароизоляцией изнутри и ветрозащитной мембраной снаружи. Требования к плитам установлены ГОСТ 9573-2012.', '2025-01-15', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Технический бюллетень производителей' AND ct.name = N'Справочная статья' AND c.name = N'Россия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Минеральная вата', 1.0), (N'Огнестойкость', 0.7), (N'Теплопроводность', 0.6), (N'Паропроницаемость', 0.5), (N'ГОСТ 9573-2012', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Минеральная вата: каменная (базальтовая) теплоизоляция';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Минвата или пенополистирол: чем утеплить фасад', N'Сравнение двух популярных утеплителей для мокрого фасада.', N'Для штукатурного фасада применяют два утеплителя: плиты каменной ваты и пенополистирол (пенопласт) ППС.

Теплопроводность у них близкая: 0,036–0,042 у минваты и 0,031–0,038 Вт/(м·К) у пенополистирола. Пенополистирол легче, дешевле в 1,5–2 раза и проще в монтаже, плиты не пылят и не требуют средств защиты.

Минеральная вата негорюча и паропроницаема. Она подходит для стен из газобетона, керамики и дерева: влага из стены свободно выходит наружу. Пенополистирол почти не пропускает пар, поэтому на паропроницаемых стенах под ним может скапливаться конденсат.

Пенополистирол горюч (группы Г1–Г4), поэтому в многоэтажных зданиях его обязательно разделяют противопожарными рассечками из минваты вокруг окон и между этажами.

Итог: для газобетона, дерева и зданий с высокими требованиями пожарной безопасности выбирайте минеральную вату; для кирпича и бетона при ограниченном бюджете подойдёт пенополистирол.', '2025-03-18', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Сравнение' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Минеральная вата', 0.9), (N'Пенополистирол', 0.9), (N'Утепление фасада', 0.9), (N'Огнестойкость', 0.5), (N'Паропроницаемость', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Минвата или пенополистирол: чем утеплить фасад';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Пенополистирол и ЭППС: в чём разница', N'Почему для фундамента и отмостки берут экструдированный пенополистирол.', N'Оба материала делают из полистирола, но по разным технологиям. Обычный пенополистирол (ППС, пенопласт) получают спеканием вспененных гранул, между которыми остаются каналы. Экструдированный пенополистирол (ЭППС, XPS) выдавливают через экструдер, и он имеет однородную структуру из закрытых ячеек.

Отсюда различия. Водопоглощение ЭППС не более 0,2–0,4 % по объёму, у ППС — 2–4 %. Прочность на сжатие ЭППС 200–500 кПа, у ППС — 70–150 кПа. Теплопроводность ЭППС 0,029–0,032 Вт/(м·К).

Поэтому ЭППС — лучший утеплитель для фундамента, цоколя, отмостки, полов по грунту и плоской эксплуатируемой кровли: он не боится воды и нагрузки. Обычный пенополистирол дешевле и подходит для фасадов, стен и перекрытий.

Оба материала горючи и разрушаются от ультрафиолета и растворителей, поэтому их закрывают штукатуркой, грунтом или стяжкой. Требования к плитам ППС — ГОСТ 15588-2014.', '2025-02-27', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Технический бюллетень производителей' AND ct.name = N'Сравнение' AND c.name = N'Россия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Пенополистирол', 0.9), (N'Экструдированный пенополистирол', 1.0), (N'Водопоглощение', 0.6), (N'Фундамент', 0.6), (N'ГОСТ 15588-2014', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Пенополистирол и ЭППС: в чём разница';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Утепление кровли и мансарды', N'Правильный пирог утеплённой скатной кровли.', N'Утеплённая скатная кровля (мансарда) состоит из слоёв, перечисленных изнутри наружу: внутренняя обшивка, пароизоляционная плёнка, утеплитель между стропилами, ветрозащитная мембрана, вентиляционный зазор (контробрешётка), обрешётка и кровельное покрытие.

Утеплитель — плиты минеральной ваты или стекловаты плотностью 30–45 кг/м³. Общая толщина для климата Беларуси — 200–250 мм. Утеплитель укладывают плотно, без щелей, в два слоя со смещением швов.

Пароизоляция обязательна: тёплый влажный воздух из дома, проникая в вату, конденсируется и намачивает её. Плёнку укладывают с нахлёстом 100–150 мм и проклеивают швы скотчем.

Вентиляционный зазор 40–50 мм между мембраной и кровлей выводит влагу и защищает металлочерепицу от конденсата. Без него утеплитель быстро теряет свойства, а стропила начинают гнить.', '2025-05-20', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Кровля', 0.9), (N'Минеральная вата', 0.7), (N'Стекловата', 0.6), (N'Пароизоляция', 0.8)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Утепление кровли и мансарды';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Металлочерепица: толщина стали и покрытие', N'На что смотреть при выборе металлочерепицы.', N'Металлочерепица — профилированный лист оцинкованной стали с полимерным покрытием, имитирующий черепицу. Это самый популярный кровельный материал для частных домов благодаря невысокой цене, малому весу (4–5 кг/м²) и быстрому монтажу.

Толщина стали — главный показатель качества: 0,45–0,5 мм. Цинковый слой — не менее 140–275 г/м². Защитное покрытие: полиэстер (дешёвый, 10–15 лет), матовый полиэстер, пурал (стойкий к ультрафиолету и царапинам, 25–30 лет), пластизол.

Минимальный уклон крыши для металлочерепицы — 14°. На меньших уклонах вода и снег задерживаются на стыках листов.

Недостатки: шум при дожде (решается утеплителем), много отходов на сложных крышах, необходимость вентиляционного зазора, иначе на нижней стороне листа образуется конденсат. Срок службы — 30–50 лет.', '2025-04-22', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Металлочерепица', 1.0), (N'Кровельный материал', 0.6), (N'Кровля', 0.6), (N'Сталь', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Металлочерепица: толщина стали и покрытие';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Профнастил, металлочерепица или мягкая кровля', N'Какое кровельное покрытие выбрать для дома, бани или гаража.', N'Профнастил — самый дешёвый вариант. Кровельный профлист с высотой волны 20–35 мм укладывают на уклон от 8°. Подходит для хозяйственных построек, гаражей и бань, но выглядит проще металлочерепицы. Требования к профилю — ГОСТ 24045-2016.

Металлочерепица дороже профнастила на 20–30 % и выглядит как черепица. Минимальный уклон 14°, срок службы 30–50 лет.

Мягкая (гибкая битумная) черепица подходит для крыш сложной формы — башенок, куполов — и почти не даёт отходов. Укладывается на сплошное основание из OSB или фанеры, поэтому итоговая стоимость выше. Не шумит при дожде. Уклон от 12°.

Керамическая черепица — самый долговечный (более 100 лет) и дорогой вариант. Масса 40–60 кг/м² требует усиленной стропильной системы. Уклон от 22°.

Для плоских крыш ни один из этих материалов не подходит — там применяют рулонную наплавляемую гидроизоляцию или мембраны.', '2025-04-25', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Сравнение' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Профнастил', 0.9), (N'Металлочерепица', 0.9), (N'Мягкая кровля', 0.9), (N'Керамическая черепица', 0.5), (N'Кровля', 0.7)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Профнастил, металлочерепица или мягкая кровля';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Мягкая кровля: устройство и основание', N'Как устроена кровля из гибкой черепицы.', N'Гибкая черепица — это плитки из стеклохолста, пропитанного модифицированным битумом и покрытого базальтовой посыпкой. Снизу находится самоклеящийся слой.

Основание делают сплошным: влагостойкая OSB-3 или фанера ФСФ толщиной 9–12 мм с зазорами 2–3 мм между плитами для температурного расширения.

По основанию раскатывают подкладочный ковёр: по всей площади при уклоне до 18°, в ендовах и по карнизам при большем уклоне. Затем монтируют карнизные планки, стартовую полосу и рядовую черепицу, прибивая каждую плитку 4–6 ершёнными гвоздями.

При низких температурах самоклеящийся слой плохо схватывается, поэтому работы ведут при температуре выше +5 °C, а зимой плитки подогревают феном.', '2025-06-01', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Обзор европейской практики' AND ct.name = N'Инструкция' AND c.name = N'Германия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Мягкая кровля', 1.0), (N'OSB', 0.6), (N'Фанера', 0.4), (N'Битум', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Мягкая кровля: устройство и основание';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Рулонная и обмазочная гидроизоляция фундамента', N'Как защитить фундамент и подвал от грунтовой воды.', N'Фундамент постоянно контактирует с влажным грунтом, поэтому без гидроизоляции бетон намокает, а при замерзании разрушается. Различают горизонтальную (между фундаментом и стеной) и вертикальную (по боковым поверхностям) гидроизоляцию.

Обмазочная гидроизоляция — битумная или битумно-полимерная мастика, наносимая в 2 слоя общей толщиной 2–4 мм. Подходит при низком уровне грунтовых вод и для мест сложной формы.

Рулонная наплавляемая гидроизоляция (на основе стеклоткани или полиэстера с битумно-полимерным слоем) наплавляется горелкой на огрунтованную праймером поверхность. Нахлёст полотен — не менее 100 мм. Применяется при высоком уровне грунтовых вод и для подвалов.

Горизонтальную отсечку между фундаментом и стеной делают из двух слоёв рулонного материала — это защищает кладку от капиллярного подсоса влаги.

Поверх гидроизоляции укладывают плиты экструдированного пенополистирола: они утепляют фундамент и защищают мастику от повреждения при обратной засыпке.', '2025-05-12', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Гидроизоляция', 0.9), (N'Рулонная гидроизоляция', 0.9), (N'Обмазочная гидроизоляция', 0.9), (N'Фундамент', 0.8)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Рулонная и обмазочная гидроизоляция фундамента';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Штукатурка: гипсовая или цементная', N'Какую штукатурку выбрать для жилых комнат, ванной и фасада.', N'Гипсовая штукатурка схватывается за 40–60 минут, даёт гладкую поверхность, которую не нужно шпатлевать перед покраской. Она пластична, не даёт усадочных трещин и регулирует влажность воздуха в комнате. Расход около 9 кг/м² на слой 10 мм.

Но гипс боится воды. Гипсовую штукатурку нельзя применять на фасадах, в неотапливаемых помещениях и в зонах прямого контакта с водой. В ванной комнате её допускается использовать только при хорошей вентиляции и под плитку с гидроизоляцией.

Цементная (цементно-песчаная) штукатурка влагостойкая и морозостойкая, подходит для фасадов, цоколя, ванных комнат, гаражей и подвалов. Она прочнее, но тяжелее, медленнее сохнет (1 день на 1 мм слоя) и требует финишной шпатлёвки.

Правило выбора: в сухих жилых комнатах — гипсовая штукатурка, во влажных помещениях и снаружи — цементная.', '2025-06-10', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Сравнение' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Штукатурка', 0.9), (N'Гипсовая штукатурка', 0.9), (N'Отделка стен', 0.8), (N'Влажные помещения', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Штукатурка: гипсовая или цементная';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Шпатлёвка: стартовая и финишная', N'Виды шпатлёвок и порядок работ.', N'Шпатлёвка (шпаклёвка) — смесь для тонкослойного выравнивания поверхности перед покраской или поклейкой обоев.

Стартовая шпатлёвка имеет крупный наполнитель и наносится слоем до 10–20 мм для заделки неровностей и швов гипсокартона. Финишная шпатлёвка — мелкодисперсная, слоем 0,5–2 мм, образует гладкую поверхность.

По вяжущему различают гипсовые (для сухих помещений), цементные (для влажных помещений и фасадов) и полимерные готовые шпатлёвки в ведрах.

Порядок работ: грунтование, стартовый слой с армирующей сеткой на проблемных местах, шлифование, грунтование, финишный слой, шлифование абразивной сеткой P180–P240 и повторное грунтование перед покраской.', '2025-06-12', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Шпатлёвка', 1.0), (N'Отделка стен', 0.7), (N'Сухая строительная смесь', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Шпатлёвка: стартовая и финишная';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Плиточный клей и укладка плитки в ванной', N'Как подготовить основание и выбрать клей для ванной комнаты.', N'В ванной комнате плитку укладывают только по гидроизоляции. Пол и стены в зоне душа на высоту 1,5–2 м покрывают обмазочной гидроизоляцией, а углы и примыкания проклеивают гидроизоляционной лентой.

Плиточный клей выбирают по классу: C1 — обычный цементный клей для керамической плитки, C2 — улучшенный, с повышенной адгезией, для керамогранита и крупного формата. Индексы: T — нет сползания на стенах, E — увеличенное время открытой выдержки, S1/S2 — эластичный клей для тёплых полов и деформирующихся оснований.

Для керамогранита из-за низкого водопоглощения нужен клей не ниже C2. Клей наносят зубчатым шпателем на основание, а для плитки больше 30×30 см — и на тыльную сторону плитки.

Затирку швов делают через 24 часа. В душевых используют эпоксидную или цементную влагостойкую затирку с противогрибковыми добавками.', '2025-07-01', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Плиточный клей', 0.9), (N'Керамическая плитка', 0.8), (N'Влажные помещения', 0.8), (N'Обмазочная гидроизоляция', 0.6)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Плиточный клей и укладка плитки в ванной';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Керамогранит или керамическая плитка', N'Чем отличается керамогранит от кафеля и что выбрать для пола.', N'Керамическую плитку (кафель) делают из глины с последующей глазуровкой. Водопоглощение 3–10 %, поэтому она не подходит для улицы. Плитка лёгкая, легко режется и применяется в основном для облицовки стен ванной и кухни.

Керамогранит прессуют под высоким давлением из смеси глины, кварцевого песка и полевого шпата и обжигают при 1200–1300 °C. Получается очень плотный материал с водопоглощением менее 0,5 %. Он морозостоек, износостоек и выдерживает высокие нагрузки.

Для пола в прихожей, на кухне, на террасе и крыльце выбирайте керамогранит. На улице — только матовый или структурированный, чтобы не скользил. Для стен в сухих зонах достаточно обычной керамической плитки.

Керамогранит тяжелее и сложнее режется, поэтому монтаж дороже. Клеить его нужно на клей класса C2.', '2025-07-08', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Обзор европейской практики' AND ct.name = N'Сравнение' AND c.name = N'Германия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Керамогранит', 1.0), (N'Керамическая плитка', 0.9), (N'Водопоглощение', 0.6), (N'Пол', 0.6)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Керамогранит или керамическая плитка';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Тротуарная плитка: толщина и основание', N'Какую тротуарную плитку брать для дорожек и парковки.', N'Тротуарная плитка (брусчатка) бывает вибропрессованной и вибролитой. Вибропрессованная плотнее и морозостойче, поэтому для улицы предпочтительна именно она.

Толщина: 40–50 мм — для садовых дорожек, 60 мм — для пешеходных зон и площадок, 80 мм и более — для въезда и парковки автомобилей. Морозостойкость должна быть не ниже F200, водопоглощение — не более 6 %. Требования установлены ГОСТ 17608-2017.

Основание под плитку для пешеходной дорожки: выемка грунта 25–30 см, геотекстиль, слой щебня фракции 20–40 мм толщиной 15 см, слой песка 5 см. Каждый слой уплотняют виброплитой. Для парковки слой щебня увеличивают до 25–30 см.

Плитку укладывают с уклоном 1–2 % для стока воды, по краям устанавливают бордюр, а швы заполняют сухим песком.', '2025-05-30', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Тротуарная плитка', 1.0), (N'Благоустройство', 0.8), (N'Морозостойкость', 0.5), (N'ГОСТ 17608-2017', 0.4), (N'Щебень', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Тротуарная плитка: толщина и основание';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Пиломатериалы: сорта и влажность древесины', N'Чем отличаются доска, брус и брусок и какую влажность выбрать.', N'Пиломатериалы получают продольной распиловкой брёвен. По соотношению размеров различают: доску (ширина больше двойной толщины), брусок (толщина до 100 мм, ширина не более двойной толщины) и брус (толщина и ширина 100 мм и более).

По ГОСТ 8486-86 пиломатериалы хвойных пород делят на сорта: отборный, 1, 2, 3 и 4. Чем ниже сорт, тем больше допускается сучков, трещин и обзола. Для несущих конструкций берут 1–2 сорт.

Влажность — важнейший показатель. Естественной влажности (свыше 22 %) древесина даёт усадку и коробится при высыхании. Для каркаса и стропил подходит древесина камерной сушки влажностью 12–18 %, для отделки — 8–12 %.

Перед монтажом пиломатериалы обрабатывают антисептиком и антипиреном: это защищает от гниения, насекомых и снижает горючесть.', '2025-03-25', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Пиломатериалы', 1.0), (N'Брус', 0.7), (N'Древесина', 0.6), (N'ГОСТ 8486-86', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Пиломатериалы: сорта и влажность древесины';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Брус для бани: клееный или профилированный', N'Какой брус выбрать для бани и чем утеплять парную.', N'Для бани чаще всего выбирают профилированный брус сечением 150×150 мм из сосны или ели камерной сушки. Профиль «шип-паз» уменьшает продуваемость стыков, а межвенцовый утеплитель (джут, лён) закрывает щели.

Клееный брус почти не даёт усадки (1–2 % против 5–8 % у профилированного), поэтому баню можно отделывать сразу после постройки. Однако клей в швах хуже переносит высокие температуры и перепады влажности, а стоимость в 2–3 раза выше.

В парной стены обшивают вагонкой из липы или осины — эти породы не выделяют смолу и мало нагреваются. Для утепления парной применяют только негорючую базальтовую минеральную вату с фольгированной пароизоляцией. Пенополистирол в бане использовать нельзя: при нагреве он выделяет вредные вещества и горит.', '2025-08-05', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Брус', 1.0), (N'Баня', 0.9), (N'Пиломатериалы', 0.5), (N'Минеральная вата', 0.3)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Брус для бани: клееный или профилированный';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'OSB и фанера: что выбрать для пола и кровли', N'Сравнение листовых материалов из древесины.', N'OSB (ориентированно-стружечная плита, ОСП) состоит из трёх-четырёх слоёв крупной щепы, склеенной водостойкими смолами. В наружных слоях щепа ориентирована вдоль плиты, во внутренних — поперёк, что даёт прочность на изгиб. Влагостойкая OSB-3 подходит для обшивки каркаса, основания кровли и черновых полов.

Фанера склеена из листов лущёного шпона с перпендикулярным направлением волокон. Фанера ФК — на карбамидном клее, для внутренних работ; ФСФ — на фенолформальдегидном клее, влагостойкая, для кровли и опалубки.

Фанера прочнее OSB на 15–20 % и лучше держит крепёж, но дороже. OSB дешевле и выпускается большими листами 2500×1250 мм, что ускоряет монтаж.

Для чернового пола под ламинат подойдёт OSB-3 толщиной 18–22 мм, для основания мягкой кровли — OSB-3 или ФСФ толщиной 9–12 мм.', '2025-02-05', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Технический бюллетень производителей' AND ct.name = N'Сравнение' AND c.name = N'Россия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'OSB', 1.0), (N'Фанера', 0.9), (N'Пол', 0.5), (N'Каркасное строительство', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'OSB и фанера: что выбрать для пола и кровли';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Стяжка или наливной пол', N'Чем выравнивать основание пола.', N'Цементно-песчаная стяжка — основной способ выравнивания пола и укрытия труб тёплого пола. Толщина 40–80 мм, на 1 м² при толщине 50 мм уходит около 90–100 кг сухой смеси М150. Стяжку армируют сеткой и укладывают по маякам. Ходить можно через 2–3 дня, укладывать покрытие — через 28 дней.

Наливной пол (самовыравнивающаяся смесь) растекается сам и даёт идеально ровную поверхность. Толщина слоя 3–10 мм для финишных составов и до 50 мм для базовых. Высыхает за несколько дней.

Наливной пол не заменяет стяжку при больших перепадах: его укладывают поверх стяжки или бетонной плиты, если перепады не превышают 10–20 мм. Для больших перепадов дешевле сначала сделать стяжку.

Под ламинат и линолеум после стяжки обычно наливают тонкий финишный слой, а под плитку достаточно ровной стяжки.', '2025-08-20', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Сравнение' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Стяжка', 0.9), (N'Наливной пол', 0.9), (N'Пол', 0.8), (N'Цемент', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Стяжка или наливной пол';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Кладка газобетона на клей', N'Технология возведения стен из газобетонных блоков.', N'Первый ряд газобетона укладывают на цементно-песчаный раствор толщиной 10–30 мм поверх горизонтальной гидроизоляции. Это позволяет выровнять основание: от точности первого ряда зависит качество всей стены.

Последующие ряды кладут на специальный клей для ячеистого бетона слоем 2–3 мм, нанося его зубчатой кареткой. Тонкий шов не создаёт мостиков холода, в отличие от растворного шва 10–12 мм.

Каждый ряд выравнивают тёркой, удаляя перепады. Перевязка швов — не менее 100–150 мм.

Армирование: первый ряд и каждый четвёртый ряд армируют двумя стержнями арматуры диаметром 8 мм, уложенными в штробы. Также армируют ряды под оконными проёмами. Над проёмами устанавливают U-блоки с арматурой или готовые перемычки.

Поверх стен под перекрытие устраивают монолитный железобетонный армопояс: он распределяет нагрузку и связывает стены.', '2025-04-15', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Кладка', 0.9), (N'Газобетон', 0.8), (N'Армирование', 0.6), (N'Строительный раствор', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Кладка газобетона на клей';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Сухие строительные смеси: классификация', N'Какие бывают сухие смеси и как их хранить.', N'Сухая строительная смесь — заводская смесь вяжущего, заполнителя и химических добавок. На объекте её только затворяют водой, что обеспечивает стабильное качество.

По назначению различают: кладочные смеси и клеи для блоков, штукатурки, шпатлёвки, плиточные клеи, смеси для пола (стяжки и наливные полы), гидроизоляционные составы, затирки.

По вяжущему: цементные (влагостойкие, для фасадов, ванных и полов), гипсовые (для сухих помещений, быстро схватываются), известковые и полимерные.

Смеси хранят в сухом помещении в заводской упаковке. Срок хранения цементных смесей — 6–12 месяцев. Затворяют смесь только чистой водой по инструкции: лишняя вода снижает прочность, а повторное разбавление схватившегося раствора недопустимо.', '2025-06-18', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Сухая строительная смесь', 1.0), (N'Штукатурка', 0.5), (N'Шпатлёвка', 0.5), (N'Плиточный клей', 0.5), (N'Наливной пол', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Сухие строительные смеси: классификация';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Что такое теплопроводность и как сравнить материалы', N'Простое объяснение коэффициента теплопроводности с таблицей значений.', N'Теплопроводность (коэффициент λ, лямбда) показывает, сколько тепла проходит через 1 м² слоя материала толщиной 1 м при разнице температур 1 градус. Единица — Вт/(м·К). Чем ниже λ, тем теплее материал.

Примерные значения: железобетон — 1,7; полнотелый керамический кирпич — 0,56–0,8; силикатный кирпич — 0,7–0,9; пустотелый кирпич — 0,35–0,5; керамический блок — 0,14–0,2; газобетон D500 — 0,12–0,14; древесина (сосна поперёк волокон) — 0,14–0,18; минеральная вата — 0,035–0,045; пенополистирол — 0,031–0,038; ЭППС — 0,029–0,032; ППУ — 0,022–0,028.

Отсюда видно, почему утеплитель толщиной 100 мм по теплозащите равен кирпичной стене толщиной около 1,5–2 метров.

Чтобы сравнить стены, считают термическое сопротивление R = толщина / λ. Например, газобетон D500 толщиной 0,4 м даёт R ≈ 3,3 м²·К/Вт. В Беларуси для наружных стен жилых зданий требуется R не менее 3,2 м²·К/Вт.', '2025-09-01', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Теплопроводность', 1.0), (N'Утеплитель', 0.6), (N'Газобетон', 0.4), (N'Керамический кирпич', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Что такое теплопроводность и как сравнить материалы';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Морозостойкость и водопоглощение: почему разрушается кирпич', N'Как вода и мороз разрушают материалы и как это предотвратить.', N'Вода, попавшая в поры материала, при замерзании расширяется примерно на 9 %. Многократные циклы замораживания и оттаивания постепенно разрушают структуру: появляются сколы, шелушение и трещины.

Морозостойкость F — это число таких циклов, которое материал выдерживает без потери более 5 % прочности. Для облицовочного кирпича нужна F50–F100, для цоколя — F75 и выше, для тротуарной плитки — F200, для бетона фундамента — F150.

Морозостойкость напрямую связана с водопоглощением: чем больше воды впитывает материал, тем быстрее он разрушается. У керамического кирпича водопоглощение 6–14 %, у силикатного 8–16 %, у керамогранита менее 0,5 %.

Чтобы продлить жизнь кладки, используют гидрофобизирующие пропитки, делают отливы и козырьки, а цоколь выкладывают из полнотелого керамического кирпича или бетона.', '2025-09-10', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Морозостойкость', 1.0), (N'Водопоглощение', 0.8), (N'Керамический кирпич', 0.5), (N'Силикатный кирпич', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Морозостойкость и водопоглощение: почему разрушается кирпич';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Пожарная безопасность материалов: группы горючести', N'Что означают обозначения НГ и Г1–Г4.', N'Строительные материалы по горючести делят на негорючие (НГ) и горючие, которые подразделяют на группы Г1 (слабогорючие), Г2 (умеренногорючие), Г3 (нормальногорючие) и Г4 (сильногорючие).

К негорючим относятся кирпич, бетон, газобетон, керамика, каменная минеральная вата, металл. Гипсокартон относится к группе Г1, огнестойкий ГКЛО дольше сохраняет целостность при пожаре благодаря армированию стекловолокном.

Пенополистирол — горючий материал (Г1–Г4 в зависимости от наличия антипиренов). Его применение в фасадах многоэтажных домов ограничено и требует противопожарных рассечек. Древесину обрабатывают антипиренами, переводя её в группу Г1–Г2.

Для путей эвакуации, бань, котельных и мест возле дымоходов применяют только негорючие материалы.', '2025-07-15', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Технический бюллетень производителей' AND ct.name = N'Обзор норматива' AND c.name = N'Россия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Огнестойкость', 1.0), (N'Минеральная вата', 0.5), (N'Пенополистирол', 0.5), (N'Огнестойкий гипсокартон', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Пожарная безопасность материалов: группы горючести';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Звукоизоляция перегородок и стен', N'Какие материалы лучше защищают от шума соседей.', N'Воздушный шум (голоса, музыка) гасится массой конструкции: чем тяжелее стена, тем лучше она изолирует звук. Поэтому силикатный кирпич и бетон — лучшие материалы для межквартирных стен. Кладка из силикатного кирпича толщиной 250 мм обеспечивает индекс звукоизоляции около 52–54 дБ.

Лёгкие перегородки работают по принципу «масса — упругость — масса»: два слоя гипсокартона на отдельных каркасах и минеральная вата между ними. Такая перегородка толщиной 125 мм может достигать 50–55 дБ при весе в 10 раз меньше кирпичной.

Газобетон и пенобетон из-за малой плотности изолируют звук хуже: перегородка из блоков D500 толщиной 100 мм — около 40–43 дБ.

Важно устранить щели и жёсткие связи: стыки с полом и потолком проклеивают виброизоляционной лентой, а розетки на соседних сторонах не располагают друг напротив друга.', '2025-08-28', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Обзор европейской практики' AND ct.name = N'Вопрос-ответ' AND c.name = N'Германия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Звукоизоляция', 1.0), (N'Перегородки', 0.8), (N'Силикатный кирпич', 0.5), (N'Минеральная вата', 0.5), (N'Гипсокартон', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Звукоизоляция перегородок и стен';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Вентилируемый фасад: устройство', N'Из чего состоит навесной вентилируемый фасад.', N'Навесной вентилируемый фасад (НВФ) — система, в которой облицовка крепится на металлической подсистеме с воздушным зазором 40–60 мм от утеплителя.

Слои системы: стена, кронштейны с терморазрывом, плиты минеральной ваты плотностью 80–100 кг/м³ (одним или двумя слоями), ветрогидрозащитная мембрана, воздушный зазор, направляющие, облицовка.

Облицовкой служат керамогранит, фиброцементные панели, композитные кассеты, сайдинг, металлопрофиль. Воздух в зазоре движется снизу вверх и удаляет влагу из утеплителя, поэтому стена остаётся сухой.

В системе применяется только негорючий утеплитель — каменная минеральная вата. Пенополистирол в вентфасадах использовать нельзя, так как воздушный зазор работает как дымоход и ускоряет распространение огня.', '2025-09-20', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Обзор европейской практики' AND ct.name = N'Инструкция' AND c.name = N'Германия';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Вентилируемый фасад', 1.0), (N'Минеральная вата', 0.7), (N'Утепление фасада', 0.7), (N'Керамогранит', 0.4)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Вентилируемый фасад: устройство';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Каркасный дом: материалы и пирог стены', N'Из каких материалов строят каркасный дом.', N'Каркасный дом строится из стоек и обвязок сечением 50×150 или 50×200 мм из сухой строганой древесины камерной сушки. Шаг стоек 600 мм соответствует ширине плит утеплителя.

Пирог стены изнутри наружу: внутренняя отделка (гипсокартон), пароизоляционная плёнка, каркас с минеральной ватой толщиной 150–200 мм, наружная обшивка OSB-3, ветрозащитная мембрана, вентзазор и фасадная отделка.

Утеплитель — минеральная или стекловата плотностью 30–40 кг/м³. Пароизоляция с внутренней стороны обязательна, иначе влага из дома будет конденсироваться в утеплителе.

Плюсы каркасного дома — быстрое строительство (2–3 месяца), лёгкий фундамент, низкие теплопотери. Минусы — горючесть каркаса, необходимость тщательного соблюдения технологии и меньшая тепловая инерция: дом быстро нагревается и быстро остывает.', '2025-10-01', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Справочная статья' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Каркасное строительство', 1.0), (N'OSB', 0.7), (N'Пиломатериалы', 0.7), (N'Минеральная вата', 0.6), (N'Пароизоляция', 0.6)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Каркасный дом: материалы и пирог стены';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Строительный раствор для кладки кирпича', N'Пропорции и марки кладочного раствора.', N'Кладочный цементно-песчаный раствор готовят из цемента, песка и воды. Марка раствора должна соответствовать марке кирпича: для стен частного дома применяют раствор М75–М100.

Пропорции для цемента М400 (по объёму): М75 — 1 часть цемента на 4 части песка; М100 — 1:3; М150 — 1:2,5. Воды добавляют до консистенции густой сметаны. Для пластичности вводят пластификатор или известковое тесто (известково-цементный раствор).

Песок должен быть чистым, без глины, крупностью до 2,5 мм. Раствор используют в течение 1,5–2 часов после приготовления, повторно разбавлять схватившийся раствор водой нельзя.

Толщина горизонтального шва в кирпичной кладке — 10–12 мм, вертикального — 8–10 мм. Летом кирпич перед кладкой смачивают, чтобы он не забрал воду из раствора.', '2025-04-05', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Строительный раствор', 1.0), (N'Кладка', 0.8), (N'Цемент', 0.6), (N'Песок', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Строительный раствор для кладки кирпича';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'ГОСТ 530-2012 и СТБ 1160-99: что регламентируют стандарты на кирпич', N'Краткое содержание нормативов на керамический кирпич и камни.', N'ГОСТ 530-2012 «Кирпич и камень керамические. Общие технические условия» распространяется на керамический кирпич и камни, применяемые для кладки и облицовки стен. В Беларуси аналогичные требования устанавливает СТБ 1160-99.

Стандарты определяют: номинальные размеры (одинарный кирпич 250×120×65 мм, полуторный 250×120×88 мм), допустимые отклонения, марки прочности М100–М300, марки морозостойкости F25–F100, классы средней плотности, водопоглощение (не менее 6 % для рядового кирпича и не более 14 % для лицевого).

Также нормируются: наличие известковых включений, высолов, трещин и отбитостей. Для лицевого кирпича задаются более жёсткие требования к внешнему виду.

Условное обозначение по ГОСТ 530-2012 выглядит так: КР-р-по 250×120×65/1НФ/150/2,0/50 — кирпич рядовой пустотелый одинарного формата, марка М150, класс плотности 2,0, морозостойкость F50.', '2025-10-15', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Учебный справочник «Строительные материалы»' AND ct.name = N'Обзор норматива' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'ГОСТ 530-2012', 1.0), (N'СТБ 1160-99', 1.0), (N'Керамический кирпич', 0.7), (N'Керамический блок', 0.5)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'ГОСТ 530-2012 и СТБ 1160-99: что регламентируют стандарты на кирпич';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Грунтовка: какую выбрать и когда она действительно нужна', N'Как отличить впитывающее основание от гладкого и подготовить стену без лишних слоёв.', N'Сначала проведите ладонью по стене: поверхность не должна осыпаться. Удалите непрочные участки и пыль. Грунтовка не превращает рыхлую штукатурку в надёжное основание.
На впитывающих минеральных поверхностях применяют совместимый грунт для регулирования впитывания. Для плотного гладкого бетона под некоторые гипсовые штукатурки нужен контактный состав с наполнителем. Это разные задачи, один продукт не заменяет другой автоматически.
Проверьте технический лист будущей штукатурки, клея или краски: там указаны тип подготовки и ограничения. Наносите грунт равномерно, без луж. Разбавляйте только тогда и в той пропорции, которую допускает изготовитель.
После выдержки убедитесь, что поверхность сухая и на ней нет стекловидной плёнки от избытка грунта. Следующий слой наносите в срок, указанный в инструкции. Пробный участок помогает проверить совместимость.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Грунтовка', 1.0), (N'Подготовка основания', 0.92), (N'Адгезия', 0.84)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Грунтовка: какую выбрать и когда она действительно нужна';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Гидроизоляция ванной: углы, трубы и порядок слоёв', N'Плитка и затирка не заменяют гидроизоляцию. Разбираем места, где чаще всего появляется протечка.', N'Начните с прочного ровного основания и заранее определите мокрые зоны, расположение слива и требуемые уклоны. Уберите пыль и подготовьте поверхность по инструкции выбранной системы.
Во внутренние углы и примыкания вклейте совместимую эластичную ленту, на выводы труб установите манжеты. Нельзя просто замазать подвижное примыкание жёстким плиточным клеем.
Нанесите гидроизоляцию в предусмотренное изготовителем число слоёв. Следите за расходом и суммарной толщиной: цвет покрытия сам по себе не подтверждает нужную толщину. Выдержите межслойные паузы и время до облицовки.
Проверьте сплошность покрытия, примыкания и отсутствие повреждений. Испытание водой проводите только если оно предусмотрено системой, после полного набора готовности и с безопасным контролем слива. Клей, лента, манжеты и гидроизоляция должны быть совместимы.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Обмазочная гидроизоляция', 1.0), (N'Гидроизоляционная лента', 0.92), (N'Влажные помещения', 0.84), (N'Плиточный клей', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Гидроизоляция ванной: углы, трубы и порядок слоёв';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Пароизоляция и мембрана: почему их нельзя менять местами', N'Два похожих рулона выполняют разные задачи. Понятная схема утеплённой скатной кровли.', N'В типовой отапливаемой мансарде пароизоляционный слой располагают со стороны помещения, а диффузионную мембрану — снаружи утеплителя. Конкретный состав кровли определяет проект и система производителя.
Пароизоляция ограничивает поступление пара в утеплитель. Работает не только полотно, но и герметичные нахлёсты, вводы кабелей, примыкания к стенам и трубам. Отверстия от крепежа и разрывы нужно устранять совместимыми материалами.
Наружная мембрана защищает утеплитель от ветра и случайной воды и позволяет конструкции высыхать наружу. Паронепроницаемая плёнка на её месте может запереть влагу.
Проверьте маркировку рулона, сторону укладки, нахлёсты и требуемые вентиляционные зазоры. Не ориентируйтесь только на цвет или гладкость плёнки: у разных продуктов правила различаются.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Сравнение' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Пароизоляция', 1.0), (N'Диффузионная мембрана', 0.92), (N'Минеральная вата', 0.84), (N'Кровля', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Пароизоляция и мембрана: почему их нельзя менять местами';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Как посчитать плитку: площадь, подрезка и запас', N'Пример для ванной: сколько упаковок покупать и почему нельзя считать только квадратные метры.', N'Измерьте каждую облицовываемую поверхность отдельно. Из площади стен вычтите проёмы, а откосы и короба добавьте отдельно. Для пола учитывайте реальную геометрию помещения и места подрезки.
Пример: поверхность 2 × 3 м имеет площадь 6 м². Если в упаковке 1,44 м², без запаса требуется округлить 6 / 1,44 вверх: получится 5 упаковок. Это 7,2 м², но количество пригодных целых плиток ещё нужно проверить по раскладке.
Запас зависит от формата, диагональной раскладки, подрезки рисунка и риска боя. Процент запаса выбирают после раскладки, а не как универсальное число для любого помещения.
Покупайте упаковки одной партии, тона и калибра. Сохраните этикетку и несколько целых плиток для будущего ремонта. Клей считают отдельно по размеру зуба, ровности основания и норме производителя.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Расчёт количества материалов', 1.0), (N'Керамическая плитка', 0.92), (N'Керамогранит', 0.84)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Как посчитать плитку: площадь, подрезка и запас';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Клей для плитки: что означают C1, C2, T, E и S1', N'Разбираем маркировку клея и подбираем его по основанию, формату и условиям эксплуатации.', N'В распространённой классификации цементных клеёв C обозначает цементную основу, C1 — базовый уровень, C2 — улучшенные показатели сцепления. T указывает на уменьшенное сползание, E — увеличенное открытое время, S1 и S2 — деформативность. Сверяйте точные требования с указанным на упаковке стандартом.
Более высокий класс не отменяет ограничений по основанию и формату. Для крупного керамогранита, тёплого пола и наружных работ важны совместимость, деформативность и возможность получить нужное заполнение под плиткой.
Клей наносят на подготовленное основание. Не укладывайте плитку на состав, у которого уже появилась поверхностная плёнка. Проверяйте перенос клея, поднимая пробную плитку.
Не исправляйте клеем перепады, превышающие допустимую толщину слоя. Количество воды, время созревания, жизнеспособность и срок включения подогрева берите из технического листа конкретного продукта.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Плиточный клей', 1.0), (N'Адгезия', 0.92), (N'Керамогранит', 0.84), (N'Пол', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Клей для плитки: что означают C1, C2, T, E и S1';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Бетон после заливки: уход важнее добавления воды', N'Как защитить молодой бетон от пересыхания и почему готовую смесь нельзя улучшать водой на глаз.', N'Прочность бетона зависит от состава, укладки, уплотнения и условий твердения. Самовольное добавление воды увеличивает водоцементное отношение и может снизить прочность и долговечность. Корректировать смесь нужно через поставщика по согласованной технологии.
Сразу после отделки защитите поверхность от солнца, ветра и быстрого испарения. Способ ухода выбирают по погоде и технологии: укрытие, поддержание влажности или совместимый плёнкообразующий состав.
Не направляйте сильную струю на ещё слабую поверхность и не допускайте резкого охлаждения. В холодную погоду нужен отдельный план температурного выдерживания; обычное увлажнение не решает проблему замерзания.
Распалубку и нагружение назначают по достигнутой прочности и проекту, а не только по количеству прошедших дней. Фиксируйте дату, температуру, поставку и мероприятия по уходу.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Бетон', 1.0), (N'Уход за бетоном', 0.92), (N'Усадка', 0.84), (N'Фундамент', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Бетон после заливки: уход важнее добавления воды';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Газобетон: первый ряд и тонкий шов', N'Чем первый выравнивающий ряд отличается от последующей кладки и что проверять до нанесения клея.', N'Первый ряд задаёт геометрию всей стены. Проверьте горизонтальность основания, оси, диагонали и предусмотренную проектом отсечную гидроизоляцию. Выравнивающий слой первого ряда выполняют по инструкции системы.
Перед последующей кладкой уберите выступы и пыль с поверхности блоков. Тонкослойный клей рассчитан на небольшую толщину и точную геометрию; им нельзя компенсировать большие перепады высоты.
Замешивайте клей по норме воды и выдерживайте технологическую паузу, если она предусмотрена. Наносите равномерно подходящим инструментом и контролируйте положение блока уровнем.
Перевязку, армирование, перемычки, опирание перекрытий и деформационные швы выполняют по проекту. Пазы и гребни не означают, что любой вертикальный шов можно оставлять без заполнения: учитывайте тип блока и место подрезки.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Газобетон', 1.0), (N'Кладка', 0.92), (N'Подготовка основания', 0.84)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Газобетон: первый ряд и тонкий шов';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Гипсокартонная перегородка: что находится внутри', N'Каркас, заполнение, обшивка и примыкания: четыре части работающей системы.', N'Перегородка — это система из профилей, крепежа, заполнения и листов. Толщину металла, шаг стоек, число слоёв и допустимую высоту выбирают по альбому систем, а не только по ширине профиля.
На примыканиях каркаса к конструкциям используют предусмотренную системой уплотняющую ленту и герметизацию. Звук может проходить через щели и обходные пути, даже если внутри лежит толстая вата.
Внутренние коммуникации размещают без повреждения стоек и листов. Закладные для шкафов и тяжёлых предметов планируют до закрытия каркаса. Розетки на противоположных сторонах стены не стоит располагать друг напротив друга без решения системы.
Стыки листов смещают согласно схеме обшивки, головки крепежа не должны рвать картон. Шпаклевание, армирующую ленту, примыкания и отделку выполняют совместимыми материалами.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Гипсокартон', 1.0), (N'Минеральная вата', 0.92), (N'Перегородки', 0.84), (N'Звукоизоляция', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Гипсокартонная перегородка: что находится внутри';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Тёплый пол под плиткой: клей, швы и первый запуск', N'Почему нельзя включать подогрев сразу после укладки и как сохранить примыкания.', N'До облицовки проверьте готовность основания: прочность, влажность, ровность и выполненные испытания системы. Тип пола, стяжки и подогрева определяет последовательность работ.
Подберите плиточный клей, прямо разрешённый для данного тёплого пола и формата плитки. Для крупных плит обычно важно нанесение на обе контактирующие поверхности и контроль заполнения.
Существующие деформационные швы основания нельзя просто перекрыть плиткой. По периметру и в предусмотренных проектом местах оставляют эластичные примыкания; жёсткая затирка их не заменяет.
Первый запуск проводят после полного срока выдержки клея, затирки и основания. Температуру повышают по регламенту системы. Использовать подогрев для ускоренного высушивания свежего клея нельзя.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Пол', 1.0), (N'Плиточный клей', 0.92), (N'Деформационный шов', 0.84), (N'Стяжка', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Тёплый пол под плиткой: клей, швы и первый запуск';
