INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Садовая дорожка: зачем геотекстиль и послойное уплотнение', N'Разделение слоёв, водоотвод и основание важнее красивого рисунка плитки.', N'Сначала определите нагрузку, грунт и путь отвода воды. Дорожка для пешеходов и площадка для автомобиля требуют разных решений. Толщины слоёв зависят от грунта, морозного пучения и нагрузки.
Геотекстиль разделяет мелкий грунт и щебёночное основание, снижая перемешивание слоёв. Выбор полотна зависит от функции, прочности и фильтрующих свойств, а не только от плотности в граммах на квадратный метр.
Щебень укладывают и уплотняют послойно подходящим оборудованием. Один толстый рыхлый слой со временем проседает. Бордюры и края должны удерживать покрытие.
Уклон и водоотвод проверяют до укладки плитки. Не направляйте воду к фундаменту и соседнему участку. Материал швов, завершающее уплотнение и уход выбирают под тип покрытия.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Геотекстиль', 1.0), (N'Тротуарная плитка', 0.92), (N'Щебень', 0.84), (N'Благоустройство', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Садовая дорожка: зачем геотекстиль и послойное уплотнение';
