INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Мостики холода: где дом теряет тепло', N'Оконные откосы, перемычки и пояса: почему одного значения толщины утеплителя недостаточно.', N'Тепловой мост возникает там, где тепло проходит легче, чем через соседние участки ограждения. Это могут быть железобетонный пояс, перемычка, край перекрытия, металлический крепёж или геометрический угол.
Проблема проявляется не только в расходах на отопление. Пониженная температура внутренней поверхности при определённой влажности может привести к конденсату и плесени.
Непрерывность теплоизоляции проверяют на узлах: откосах, цоколе, примыканиях кровли и балконных плитах. Закрыть один холодный участок изнутри без расчёта может означать перенести влагу в конструкцию.
Для диагностики сопоставляют проект, фактический монтаж, влажность помещений и вентиляцию. Тепловизионную съёмку выполняют при подходящих условиях, а узлы исправляют по расчётному решению.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Мостик холода', 1.0), (N'Теплопроводность', 0.92), (N'Наружные стены', 0.84), (N'Утеплитель', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Мостики холода: где дом теряет тепло';
