INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Минеральная вата: выбираем по назначению, а не только по плотности', N'Мягкий мат, фасадная плита и плита под стяжку не являются взаимозаменяемыми.', N'Для утепления важны теплопроводность в расчётных условиях, стабильность размеров, водопоглощение и механические свойства. Плотность помогает описать продукт, но не заменяет его назначение и технический лист.
В ненагруженной скатной кровле и каркасной стене используют изделия, предусмотренные для установки между элементами каркаса. Под штукатурный фасад нужны плиты, допущенные в конкретную фасадную систему.
Под стяжкой или кровельным ковром утеплитель воспринимает нагрузку. Здесь проверяют прочность при сжатии и другие характеристики, которые нельзя узнать только по внешнему виду плиты.
Храните упаковки сухими и защищайте материал от намокания во время монтажа. При работе используйте средства защиты, указанные изготовителем, и не перекрывайте предусмотренные вентиляционные каналы.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Минеральная вата', 1.0), (N'Утеплитель', 0.92), (N'Кровля', 0.84), (N'Утепление фасада', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Минеральная вата: выбираем по назначению, а не только по плотности';
