INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Штукатурка треснула: проверяем причину до ремонта', N'Усадка, слабое основание и подвижный стык требуют разных способов исправления.', N'Сначала определите, меняется ли трещина со временем и связана ли она с конструкцией. Растущие трещины, смещение кромок и деформации конструкций требуют обследования специалистом до косметического ремонта.
Тонкая сетка трещин может быть связана с быстрым высыханием, лишней водой или нарушением допустимой толщины слоя. Отслоение часто связано с пылью, недостаточной прочностью основания и несовместимостью материалов.
На границе разных оснований может потребоваться специальное армирование или деформационное примыкание. Заклеивание любой трещины сеткой не устраняет движение конструкции.
Удалите непрочные участки, устраните причину, подготовьте основание и выполните пробный ремонт совместимой системой. Не сушите свежую штукатурку направленным горячим воздухом.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Штукатурка', 1.0), (N'Усадка', 0.92), (N'Подготовка основания', 0.84)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Штукатурка треснула: проверяем причину до ремонта';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Хранение цемента и сухих смесей: как не купить испорченный мешок', N'Срок годности, целая упаковка и сухое хранение до начала ремонта.', N'Перед покупкой проверьте дату изготовления, срок хранения и целостность мешка. Продукты разных типов могут иметь разные сроки и условия хранения; универсального срока для всех смесей нет.
Храните мешки в сухом закрытом помещении на поддонах, отдельно от влажного пола и стен. Защитите упаковку от дождя и конденсата при перевозке.
Твёрдые комки, которые не рассыпаются, могут указывать на преждевременную гидратацию. Просеивание не возвращает исходные свойства вяжущего. Для ответственных работ повреждённый продукт не используйте.
Открытый мешок плотно закрывайте и расходуйте в срок, разрешённый производителем. Не смешивайте остатки неизвестных продуктов и не добавляйте свежую смесь в уже схватившийся раствор.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Цемент', 1.0), (N'Сухая строительная смесь', 0.92), (N'Плиточный клей', 0.84)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Хранение цемента и сухих смесей: как не купить испорченный мешок';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Как читать технический лист строительного материала', N'Пять пунктов, которые нужно проверить до покупки: назначение, основание, расход, время и ограничения.', N'Начните с назначения: внутри или снаружи, сухая или влажная зона, основание минеральное, деревянное или листовое. Сверьте точное название и версию документа с упаковкой.
Найдите требования к основанию и подготовке: прочность, допустимую влажность, возраст, грунтование и минимальную температуру. Отдельно проверьте запреты.
Расход зависит от толщины, ровности и инструмента. Не сравнивайте цену килограмма без пересчёта на свою площадь и толщину. Учитывайте минимальную и максимальную толщину одного слоя.
Различайте жизнеспособность раствора в ведре, открытое время на основании, время корректировки и срок до следующей операции. Это разные интервалы. Сохраните PDF или фото маркировки вместе с расчётами проекта.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Расчёт количества материалов', 1.0), (N'Подготовка основания', 0.92), (N'Адгезия', 0.84)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Как читать технический лист строительного материала';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Плитка на улице: морозостойкость и вода под покрытием', N'Даже морозостойкая плитка может отслоиться, если основание и клеевой слой удерживают воду.', N'Для наружной облицовки выбирают материал, разрешённый для улицы, с подходящей морозостойкостью и противоскольжением. Гладкая плитка для внутренних стен не становится безопасной у входа только из-за низкого водопоглощения.
Основание должно отводить воду. Уклон, гидроизоляция, примыкания и водосброс формируют систему. Пустоты под плиткой накапливают воду и повышают риск разрушения при замерзании.
Клей и затирку подбирают для наружных условий и формата. Контролируют заполнение клеевого слоя и сохраняют предусмотренные деформационные швы.
Работы выполняют в допустимом температурном диапазоне без дождя, заморозков и быстрого пересыхания на солнце. Готовое покрытие защищают на время твердения, указанное в документации.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Вопрос-ответ' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Керамогранит', 1.0), (N'Морозостойкость', 0.92), (N'Гидроизоляция', 0.84), (N'Деформационный шов', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Плитка на улице: морозостойкость и вода под покрытием';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Ремонт по шагам: что делать до покупки материалов', N'Понятный маршрут от обмера комнаты до закупки совместимых материалов.', N'Сформулируйте задачу: какое помещение, какие нагрузки, влажность и желаемое покрытие. Сфотографируйте проблемные места и запишите размеры. Сначала устраните протечки и другие причины повреждений.
Проверьте основание. Его прочность, ровность и влажность определяют состав работ и расход материалов. Завершите скрытые инженерные работы до финишной отделки.
Подбирайте совместимую систему: основание, грунт, выравнивающий слой, гидроизоляция при необходимости, клей или краска. Проверьте паузы между операциями и допустимый микроклимат.
Составьте ведомость материалов с единицами измерения, расходом, округлением до упаковок и обоснованным запасом. Сохраните инструкции и этикетки: они пригодятся для обслуживания и точечного ремонта.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Инструкция' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Расчёт количества материалов', 1.0), (N'Подготовка основания', 0.92), (N'Отделка стен', 0.84)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Ремонт по шагам: что делать до покупки материалов';
GO

INSERT INTO kb.Material (title, summary, body, publish_date, id_izdanie, id_type, id_country)
SELECT N'Как сравнить утеплители: теплопроводность, толщина и условия', N'Что показывает формула R = δ / λ и почему расчёт слоя не заменяет расчёт всей стены.', N'Тепловое сопротивление однородного слоя приближённо определяют как R = δ / λ, где δ — толщина в метрах, λ — теплопроводность в Вт/(м·К). При одинаковой толщине меньшая λ даёт большее сопротивление.
Пример: слой 0,10 м при λ = 0,040 имеет R = 2,5 м²·К/Вт. Для λ = 0,035 при той же толщине получается около 2,86. Это сравнение одного слоя, а не готовое решение для дома.
Сравнивайте значения λ при одинаковых условиях. Влажность и температура влияют на показатели. Паспортное значение для сухого образца и расчётное значение для условий эксплуатации могут различаться.
Для выбора системы дополнительно проверяют пожарные требования, влагорежим, нагрузки, крепление и мостики холода. Требуемую толщину всей конструкции определяют по проекту и нормам региона.', '2026-11-19', p.id_izdanie, ct.id_type, c.id_country
FROM kb.Publisher AS p, kb.ContentType AS ct, kb.Country AS c
WHERE p.name = N'Редакция портала «СтройМир»' AND ct.name = N'Сравнение' AND c.name = N'Беларусь';
INSERT INTO kb.MaterialTag (id_material, id_tag, relevance)
SELECT m.id_material, t.id_tag, v.rel
FROM (VALUES (N'Утеплитель', 1.0), (N'Теплопроводность', 0.92), (N'Минеральная вата', 0.84), (N'Экструдированный пенополистирол', 0.76)) AS v(tag, rel)
JOIN kb.Tag AS t ON t.name = v.tag
JOIN kb.Material AS m ON m.title = N'Как сравнить утеплители: теплопроводность, толщина и условия';
GO

