INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Из чего делают керамический кирпич, какие бывают марки прочности и морозостойкости и где его применяют.", "takeaways": ["Керамический кирпич изготавливают из глины с добавками, формуют и обжигают при температуре 950–1050 °C.", "Прочность обозначается маркой М: М100, М125, М150, М175, М200.", "Морозостойкость обозначают маркой F: F25, F35, F50, F75, F100."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Керамический кирпич: свойства, марки и применение';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Белый кирпич из извести и песка: где его можно применять, а где нельзя.", "takeaways": ["Силикатный кирпич производят из кварцевого песка (около 90 %) и извести (около 10 %) методом автоклавного твердения: смесь прессуют и выдерживают паром под давлением при температуре 170–200 °C.", "Плотность силикатного кирпича 1800–1950 кг/м³, теплопроводность 0,7–0,9 Вт/(м·К), поэтому стены из него холоднее, чем из керамики, и требуют утепления.", "Главный недостаток — повышенное водопоглощение (8–16 %) и меньшая стойкость к постоянному увлажнению."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Силикатный кирпич: плюсы, минусы и ограничения';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Марки плотности D300–D600, теплопроводность и прочность газобетонных блоков.", "takeaways": ["Газобетон (газосиликатный блок) — автоклавный ячеистый бетон.", "Марка по плотности D показывает массу кубометра в килограммах: D300, D400, D500, D600.", "Теплопроводность газобетона D500 в сухом состоянии около 0,12 Вт/(м·К) — в 4–5 раз меньше, чем у керамического кирпича."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "wall.svg", "alt": "Учебная схема кладки из блоков", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Газобетон: тёплая стена без утеплителя?';
