INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Сравнение двух видов ячеистого бетона по прочности, геометрии и стабильности качества.", "takeaways": ["Газобетон и пенобетон относятся к ячеистым бетонам, но производятся по-разному.", "Газобетон почти всегда автоклавный и выпускается на крупных заводах, поэтому у него стабильная плотность и точная геометрия (отклонения до 1–2 мм).", "Пенобетон с закрытыми порами меньше впитывает воду, но при одинаковой плотности прочнее газобетон."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "wall.svg", "alt": "Учебная схема кладки из блоков", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Газобетон или пенобетон: что выбрать';
