INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Как читать маркировку цемента и какой цемент выбрать для фундамента, стяжки и кладки.", "takeaways": ["Цемент получают помолом клинкера с гипсом (3–5 %) и минеральными добавками.", "По старой маркировке «М500 Д0» означает: марка прочности 500 кгс/см², Д0 — без минеральных добавок.", "По ГОСТ 31108-2020 используется европейская маркировка: ЦЕМ I 42,5Н."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Цемент М500 Д0 и новая маркировка ЦЕМ';
