INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "water", "topic_name": "Влага и фундамент", "minutes": 2, "plain": "Какой бетон заказать для ленточного фундамента частного дома.", "takeaways": ["Прочность бетона обозначают классом B (гарантированная прочность в МПа) или маркой М (средняя прочность в кгс/см²).", "Для ленточного фундамента частного дома из газобетона или каркаса достаточно бетона B20 (М250).", "Кроме прочности важны морозостойкость F (для фундамента — не ниже F150), водонепроницаемость W (не ниже W4–W6) и подвижность смеси П (для заливки в опалубку с арматурой — П3–П4)."], "steps": ["Определите источник воды и требования проекта к конструкции.", "Подготовьте основание, примыкания и проходки до основного покрытия.", "Проверьте сплошность защиты до обратной засыпки или закрытия отделкой."], "mistakes": ["Подменять гидроизоляцию обычным плиточным клеем.", "Нагружать свежий бетон по календарю без оценки набранной прочности."], "image": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "caption": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента."}, "videos": [], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Класс бетона и марка: как выбрать бетон для фундамента';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "water", "topic_name": "Влага и фундамент", "minutes": 2, "plain": "Почему бетон армируют и как устроен арматурный каркас ленточного фундамента.", "takeaways": ["Бетон хорошо работает на сжатие, но плохо на растяжение: его прочность при растяжении примерно в 10 раз ниже.", "Для ленточного фундамента применяют рабочую арматуру периодического профиля диаметром 10–14 мм класса А500С (А-III).", "Защитный слой бетона — расстояние от арматуры до поверхности — должен быть не менее 40 мм, иначе сталь начнёт ржаветь."], "steps": ["Определите источник воды и требования проекта к конструкции.", "Подготовьте основание, примыкания и проходки до основного покрытия.", "Проверьте сплошность защиты до обратной засыпки или закрытия отделкой."], "mistakes": ["Подменять гидроизоляцию обычным плиточным клеем.", "Нагружать свежий бетон по календарю без оценки набранной прочности."], "image": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "caption": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента."}, "videos": [], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Железобетон и армирование фундамента';
