INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "insulation", "topic_name": "Утепление дома", "minutes": 2, "plain": "Свойства, плотность и области применения каменной ваты.", "takeaways": ["Каменную (базальтовую) минеральную вату получают из расплава горных пород габбро-базальтовой группы при температуре около 1500 °C.", "Теплопроводность минеральной ваты 0,035–0,045 Вт/(м·К).", "Плотность плит выбирают по нагрузке: 30–45 кг/м³ — для скатной кровли и каркасных стен, 80–100 кг/м³ — для вентилируемых фасадов, 125–150 кг/м³ — для штукатурного (мокрого) фасада и плоской кровли."], "steps": ["Выберите материал, разрешённый для конкретной конструкции и нагрузки.", "Проверьте непрерывность утепления на откосах, цоколе и примыканиях.", "Защитите материал от намокания и проверьте крепление до закрытия слоя."], "mistakes": ["Сравнивать только плотность без назначения продукта.", "Оставлять щели между плитами или закрывать мокрый утеплитель."], "image": {"file": "wool.jpg", "alt": "Монтаж волокнистого утеплителя", "author": "Erik Mclean", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/unrecognizable-worker-insulating-with-stone-wool-6124239/", "download": "https://images.pexels.com/photos/6124239/pexels-photo-6124239.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "insulation.svg", "alt": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему.", "caption": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему."}, "videos": [{"title": "Утепление фасада: Дом за год", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "n_MstVbMNA0", "url": "https://www.youtube.com/watch?v=n_MstVbMNA0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Минеральная вата: каменная (базальтовая) теплоизоляция';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "insulation", "topic_name": "Утепление дома", "minutes": 2, "plain": "Сравнение двух популярных утеплителей для мокрого фасада.", "takeaways": ["Для штукатурного фасада применяют два утеплителя: плиты каменной ваты и пенополистирол (пенопласт) ППС.", "Теплопроводность у них близкая: 0,036–0,042 у минваты и 0,031–0,038 Вт/(м·К) у пенополистирола.", "Минеральная вата негорюча и паропроницаема."], "steps": ["Выберите материал, разрешённый для конкретной конструкции и нагрузки.", "Проверьте непрерывность утепления на откосах, цоколе и примыканиях.", "Защитите материал от намокания и проверьте крепление до закрытия слоя."], "mistakes": ["Сравнивать только плотность без назначения продукта.", "Оставлять щели между плитами или закрывать мокрый утеплитель."], "image": {"file": "insulation.svg", "alt": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "insulation.svg", "alt": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему.", "caption": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему."}, "videos": [{"title": "Утепление фасада: Дом за год", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "n_MstVbMNA0", "url": "https://www.youtube.com/watch?v=n_MstVbMNA0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Минвата или пенополистирол: чем утеплить фасад';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "water", "topic_name": "Влага и фундамент", "minutes": 2, "plain": "Почему для фундамента и отмостки берут экструдированный пенополистирол.", "takeaways": ["Оба материала делают из полистирола, но по разным технологиям.", "Отсюда различия.", "Поэтому ЭППС — лучший утеплитель для фундамента, цоколя, отмостки, полов по грунту и плоской эксплуатируемой кровли: он не боится воды и нагрузки."], "steps": ["Определите источник воды и требования проекта к конструкции.", "Подготовьте основание, примыкания и проходки до основного покрытия.", "Проверьте сплошность защиты до обратной засыпки или закрытия отделкой."], "mistakes": ["Подменять гидроизоляцию обычным плиточным клеем.", "Нагружать свежий бетон по календарю без оценки набранной прочности."], "image": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "caption": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента."}, "videos": [], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Пенополистирол и ЭППС: в чём разница';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "roof", "topic_name": "Кровля и мансарда", "minutes": 2, "plain": "Правильный пирог утеплённой скатной кровли.", "takeaways": ["Утеплённая скатная кровля (мансарда) состоит из слоёв, перечисленных изнутри наружу: внутренняя обшивка, пароизоляционная плёнка, утеплитель между стропилами, ветрозащитная мембрана, вентиляционный зазор (контробрешётка), обрешётка и кровельное покрытие.", "Утеплитель — плиты минеральной ваты или стекловаты плотностью 30–45 кг/м³.", "Пароизоляция обязательна: тёплый влажный воздух из дома, проникая в вату, конденсируется и намачивает её."], "steps": ["Проверьте проектный состав кровли и назначение каждой плёнки.", "Герметично выполните внутренние примыкания и проходки.", "Сохраните предусмотренные вентиляционные зазоры и путь выхода воздуха."], "mistakes": ["Поменять местами пароизоляцию и диффузионную мембрану.", "Перекрыть выход воздуха утеплителем или отделкой."], "image": {"file": "roof.jpg", "alt": "Монтаж керамической кровельной черепицы", "author": "Clément Proust", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/installation-of-red-clay-roof-tiles-on-new-building-31771167/", "download": "https://images.pexels.com/photos/31771167/pexels-photo-31771167.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "roof.svg", "alt": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор.", "caption": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор."}, "videos": [{"title": "Теплоизоляция крыши: каменная вата и PIR", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "OcIOrGdhFG0", "url": "https://www.youtube.com/watch?v=OcIOrGdhFG0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Утепление кровли и мансарды';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "roof", "topic_name": "Кровля и мансарда", "minutes": 2, "plain": "На что смотреть при выборе металлочерепицы.", "takeaways": ["Металлочерепица — профилированный лист оцинкованной стали с полимерным покрытием, имитирующий черепицу.", "Толщина стали — главный показатель качества: 0,45–0,5 мм.", "Минимальный уклон крыши для металлочерепицы — 14°."], "steps": ["Проверьте проектный состав кровли и назначение каждой плёнки.", "Герметично выполните внутренние примыкания и проходки.", "Сохраните предусмотренные вентиляционные зазоры и путь выхода воздуха."], "mistakes": ["Поменять местами пароизоляцию и диффузионную мембрану.", "Перекрыть выход воздуха утеплителем или отделкой."], "image": {"file": "roof.jpg", "alt": "Монтаж керамической кровельной черепицы", "author": "Clément Proust", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/installation-of-red-clay-roof-tiles-on-new-building-31771167/", "download": "https://images.pexels.com/photos/31771167/pexels-photo-31771167.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "roof.svg", "alt": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор.", "caption": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор."}, "videos": [{"title": "Теплоизоляция крыши: каменная вата и PIR", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "OcIOrGdhFG0", "url": "https://www.youtube.com/watch?v=OcIOrGdhFG0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Металлочерепица: толщина стали и покрытие';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "roof", "topic_name": "Кровля и мансарда", "minutes": 2, "plain": "Какое кровельное покрытие выбрать для дома, бани или гаража.", "takeaways": ["Профнастил — самый дешёвый вариант.", "Металлочерепица дороже профнастила на 20–30 % и выглядит как черепица.", "Мягкая (гибкая битумная) черепица подходит для крыш сложной формы — башенок, куполов — и почти не даёт отходов."], "steps": ["Проверьте проектный состав кровли и назначение каждой плёнки.", "Герметично выполните внутренние примыкания и проходки.", "Сохраните предусмотренные вентиляционные зазоры и путь выхода воздуха."], "mistakes": ["Поменять местами пароизоляцию и диффузионную мембрану.", "Перекрыть выход воздуха утеплителем или отделкой."], "image": {"file": "roof.jpg", "alt": "Монтаж керамической кровельной черепицы", "author": "Clément Proust", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/installation-of-red-clay-roof-tiles-on-new-building-31771167/", "download": "https://images.pexels.com/photos/31771167/pexels-photo-31771167.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "roof.svg", "alt": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор.", "caption": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор."}, "videos": [{"title": "Теплоизоляция крыши: каменная вата и PIR", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "OcIOrGdhFG0", "url": "https://www.youtube.com/watch?v=OcIOrGdhFG0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Профнастил, металлочерепица или мягкая кровля';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "roof", "topic_name": "Кровля и мансарда", "minutes": 2, "plain": "Как устроена кровля из гибкой черепицы.", "takeaways": ["Гибкая черепица — это плитки из стеклохолста, пропитанного модифицированным битумом и покрытого базальтовой посыпкой.", "Основание делают сплошным: влагостойкая OSB-3 или фанера ФСФ толщиной 9–12 мм с зазорами 2–3 мм между плитами для температурного расширения.", "По основанию раскатывают подкладочный ковёр: по всей площади при уклоне до 18°, в ендовах и по карнизам при большем уклоне."], "steps": ["Проверьте проектный состав кровли и назначение каждой плёнки.", "Герметично выполните внутренние примыкания и проходки.", "Сохраните предусмотренные вентиляционные зазоры и путь выхода воздуха."], "mistakes": ["Поменять местами пароизоляцию и диффузионную мембрану.", "Перекрыть выход воздуха утеплителем или отделкой."], "image": {"file": "roof.jpg", "alt": "Монтаж керамической кровельной черепицы", "author": "Clément Proust", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/installation-of-red-clay-roof-tiles-on-new-building-31771167/", "download": "https://images.pexels.com/photos/31771167/pexels-photo-31771167.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "roof.svg", "alt": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор.", "caption": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор."}, "videos": [{"title": "Теплоизоляция крыши: каменная вата и PIR", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "OcIOrGdhFG0", "url": "https://www.youtube.com/watch?v=OcIOrGdhFG0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Мягкая кровля: устройство и основание';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "water", "topic_name": "Влага и фундамент", "minutes": 2, "plain": "Как защитить фундамент и подвал от грунтовой воды.", "takeaways": ["Фундамент постоянно контактирует с влажным грунтом, поэтому без гидроизоляции бетон намокает, а при замерзании разрушается.", "Обмазочная гидроизоляция — битумная или битумно-полимерная мастика, наносимая в 2 слоя общей толщиной 2–4 мм.", "Рулонная наплавляемая гидроизоляция (на основе стеклоткани или полиэстера с битумно-полимерным слоем) наплавляется горелкой на огрунтованную праймером поверхность."], "steps": ["Определите источник воды и требования проекта к конструкции.", "Подготовьте основание, примыкания и проходки до основного покрытия.", "Проверьте сплошность защиты до обратной засыпки или закрытия отделкой."], "mistakes": ["Подменять гидроизоляцию обычным плиточным клеем.", "Нагружать свежий бетон по календарю без оценки набранной прочности."], "image": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "caption": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента."}, "videos": [{"title": "Гидроизоляция фундамента частного дома", "author": "ТЕХНОНИКОЛЬ", "provider": "Rutube", "url": "https://rutube.ru/video/35e9cd2db5a2af87a4d31857d52aa6fd/", "source": "https://rutube.ru/video/35e9cd2db5a2af87a4d31857d52aa6fd/"}], "sources": ["https://www.tn.ru/", "https://rutube.ru/video/35e9cd2db5a2af87a4d31857d52aa6fd/"]}' FROM kb.Material WHERE title=N'Рулонная и обмазочная гидроизоляция фундамента';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Какую штукатурку выбрать для жилых комнат, ванной и фасада.", "takeaways": ["Гипсовая штукатурка схватывается за 40–60 минут, даёт гладкую поверхность, которую не нужно шпатлевать перед покраской.", "Но гипс боится воды.", "Цементная (цементно-песчаная) штукатурка влагостойкая и морозостойкая, подходит для фасадов, цоколя, ванных комнат, гаражей и подвалов."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Штукатурка: гипсовая или цементная';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Виды шпатлёвок и порядок работ.", "takeaways": ["Шпатлёвка (шпаклёвка) — смесь для тонкослойного выравнивания поверхности перед покраской или поклейкой обоев.", "Стартовая шпатлёвка имеет крупный наполнитель и наносится слоем до 10–20 мм для заделки неровностей и швов гипсокартона.", "По вяжущему различают гипсовые (для сухих помещений), цементные (для влажных помещений и фасадов) и полимерные готовые шпатлёвки в ведрах."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Шпатлёвка: стартовая и финишная';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Как подготовить основание и выбрать клей для ванной комнаты.", "takeaways": ["В ванной комнате плитку укладывают только по гидроизоляции.", "Плиточный клей выбирают по классу: C1 — обычный цементный клей для керамической плитки, C2 — улучшенный, с повышенной адгезией, для керамогранита и крупного формата.", "Для керамогранита из-за низкого водопоглощения нужен клей не ниже C2."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [{"title": "Гидроизоляция под плиткой", "author": "Ceresit Беларусь", "provider": "YouTube", "youtube_id": "JwEucXTm9H0", "url": "https://www.youtube.com/watch?v=JwEucXTm9H0", "source": "https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html"}, {"title": "Укладка плитки из натурального камня", "author": "Ceresit Беларусь", "provider": "YouTube", "youtube_id": "Q-apGS9Gm2A", "url": "https://www.youtube.com/watch?v=Q-apGS9Gm2A", "source": "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-lay.html"}, {"title": "Заполнение швов плитки", "author": "Ceresit Беларусь", "provider": "YouTube", "youtube_id": "uHf18LaVJv8", "url": "https://www.youtube.com/watch?v=uHf18LaVJv8", "source": "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-grout.html"}], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html", "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-lay.html", "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-grout.html"]}' FROM kb.Material WHERE title=N'Плиточный клей и укладка плитки в ванной';
