INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "garden", "topic_name": "Дорожки и участок", "minutes": 2, "plain": "Какую тротуарную плитку брать для дорожек и парковки.", "takeaways": ["Тротуарная плитка (брусчатка) бывает вибропрессованной и вибролитой.", "Толщина: 40–50 мм — для садовых дорожек, 60 мм — для пешеходных зон и площадок, 80 мм и более — для въезда и парковки автомобилей.", "Основание под плитку для пешеходной дорожки: выемка грунта 25–30 см, геотекстиль, слой щебня фракции 20–40 мм толщиной 15 см, слой песка 5 см."], "steps": ["Определите нагрузку и направление стока воды.", "Разделите грунт и основание подходящим геотекстилем, если он предусмотрен.", "Уплотняйте основание послойно и контролируйте уклон до укладки покрытия."], "mistakes": ["Уплотнять один толстый слой щебня вместо нескольких тонких.", "Направлять сток к дому или на соседний участок."], "image": {"file": "paving.svg", "alt": "Основание дорожки: покрытие, выравнивающий слой, уплотнённый щебень, разделение и грунт. Толщины зависят от нагрузки и грунта.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "paving.svg", "alt": "Основание дорожки: покрытие, выравнивающий слой, уплотнённый щебень, разделение и грунт. Толщины зависят от нагрузки и грунта.", "caption": "Основание дорожки: покрытие, выравнивающий слой, уплотнённый щебень, разделение и грунт. Толщины зависят от нагрузки и грунта."}, "videos": [], "sources": []}' FROM kb.Material WHERE title=N'Тротуарная плитка: толщина и основание';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Чем отличаются доска, брус и брусок и какую влажность выбрать.", "takeaways": ["Пиломатериалы получают продольной распиловкой брёвен.", "По ГОСТ 8486-86 пиломатериалы хвойных пород делят на сорта: отборный, 1, 2, 3 и 4.", "Влажность — важнейший показатель."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "osb.jpg", "alt": "Структура ориентированно-стружечной плиты OSB", "author": "Engin Akyurt", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/rough-surface-of-a-wooden-board-9756487/", "download": "https://images.pexels.com/photos/9756487/pexels-photo-9756487.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Пиломатериалы: сорта и влажность древесины';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "insulation", "topic_name": "Утепление дома", "minutes": 2, "plain": "Какой брус выбрать для бани и чем утеплять парную.", "takeaways": ["Для бани чаще всего выбирают профилированный брус сечением 150×150 мм из сосны или ели камерной сушки.", "Клееный брус почти не даёт усадки (1–2 % против 5–8 % у профилированного), поэтому баню можно отделывать сразу после постройки.", "В парной стены обшивают вагонкой из липы или осины — эти породы не выделяют смолу и мало нагреваются."], "steps": ["Выберите материал, разрешённый для конкретной конструкции и нагрузки.", "Проверьте непрерывность утепления на откосах, цоколе и примыканиях.", "Защитите материал от намокания и проверьте крепление до закрытия слоя."], "mistakes": ["Сравнивать только плотность без назначения продукта.", "Оставлять щели между плитами или закрывать мокрый утеплитель."], "image": {"file": "osb.jpg", "alt": "Структура ориентированно-стружечной плиты OSB", "author": "Engin Akyurt", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/rough-surface-of-a-wooden-board-9756487/", "download": "https://images.pexels.com/photos/9756487/pexels-photo-9756487.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "insulation.svg", "alt": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему.", "caption": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему."}, "videos": [{"title": "Утепление фасада: Дом за год", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "n_MstVbMNA0", "url": "https://www.youtube.com/watch?v=n_MstVbMNA0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Брус для бани: клееный или профилированный';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Сравнение листовых материалов из древесины.", "takeaways": ["OSB (ориентированно-стружечная плита, ОСП) состоит из трёх-четырёх слоёв крупной щепы, склеенной водостойкими смолами.", "Фанера склеена из листов лущёного шпона с перпендикулярным направлением волокон.", "Фанера прочнее OSB на 15–20 % и лучше держит крепёж, но дороже."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "osb.jpg", "alt": "Структура ориентированно-стружечной плиты OSB", "author": "Engin Akyurt", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/rough-surface-of-a-wooden-board-9756487/", "download": "https://images.pexels.com/photos/9756487/pexels-photo-9756487.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'OSB и фанера: что выбрать для пола и кровли';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Чем выравнивать основание пола.", "takeaways": ["Цементно-песчаная стяжка — основной способ выравнивания пола и укрытия труб тёплого пола.", "Наливной пол (самовыравнивающаяся смесь) растекается сам и даёт идеально ровную поверхность.", "Наливной пол не заменяет стяжку при больших перепадах: его укладывают поверх стяжки или бетонной плиты, если перепады не превышают 10–20 мм."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Стяжка или наливной пол';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Технология возведения стен из газобетонных блоков.", "takeaways": ["Первый ряд газобетона укладывают на цементно-песчаный раствор толщиной 10–30 мм поверх горизонтальной гидроизоляции.", "Последующие ряды кладут на специальный клей для ячеистого бетона слоем 2–3 мм, нанося его зубчатой кареткой.", "Каждый ряд выравнивают тёркой, удаляя перепады."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "wall.svg", "alt": "Учебная схема кладки из блоков", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Кладка газобетона на клей';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Какие бывают сухие смеси и как их хранить.", "takeaways": ["Сухая строительная смесь — заводская смесь вяжущего, заполнителя и химических добавок.", "По назначению различают: кладочные смеси и клеи для блоков, штукатурки, шпатлёвки, плиточные клеи, смеси для пола (стяжки и наливные полы), гидроизоляционные составы, затирки.", "По вяжущему: цементные (влагостойкие, для фасадов, ванных и полов), гипсовые (для сухих помещений, быстро схватываются), известковые и полимерные."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Сухие строительные смеси: классификация';
