INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Простое объяснение коэффициента теплопроводности с таблицей значений.", "takeaways": ["Теплопроводность (коэффициент λ, лямбда) показывает, сколько тепла проходит через 1 м² слоя материала толщиной 1 м при разнице температур 1 градус.", "Примерные значения: железобетон — 1,7; полнотелый керамический кирпич — 0,56–0,8; силикатный кирпич — 0,7–0,9; пустотелый кирпич — 0,35–0,5; керамический блок — 0,14–0,2; газобетон D500 — 0,12–0,14; древесина (сосна поперёк волокон) — 0,14–0,18; минеральная вата — 0,035–0,045; пенополистирол — 0,031–0,038; ЭППС — 0,029–0,032; ППУ — 0,022–0,028.", "Отсюда видно, почему утеплитель толщиной 100 мм по теплозащите равен кирпичной стене толщиной около 1,5–2 метров."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Что такое теплопроводность и как сравнить материалы';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Как вода и мороз разрушают материалы и как это предотвратить.", "takeaways": ["Вода, попавшая в поры материала, при замерзании расширяется примерно на 9 %.", "Морозостойкость F — это число таких циклов, которое материал выдерживает без потери более 5 % прочности.", "Морозостойкость напрямую связана с водопоглощением: чем больше воды впитывает материал, тем быстрее он разрушается."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Морозостойкость и водопоглощение: почему разрушается кирпич';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "insulation", "topic_name": "Утепление дома", "minutes": 2, "plain": "Что означают обозначения НГ и Г1–Г4.", "takeaways": ["Строительные материалы по горючести делят на негорючие (НГ) и горючие, которые подразделяют на группы Г1 (слабогорючие), Г2 (умеренногорючие), Г3 (нормальногорючие) и Г4 (сильногорючие).", "К негорючим относятся кирпич, бетон, газобетон, керамика, каменная минеральная вата, металл.", "Пенополистирол — горючий материал (Г1–Г4 в зависимости от наличия антипиренов)."], "steps": ["Выберите материал, разрешённый для конкретной конструкции и нагрузки.", "Проверьте непрерывность утепления на откосах, цоколе и примыканиях.", "Защитите материал от намокания и проверьте крепление до закрытия слоя."], "mistakes": ["Сравнивать только плотность без назначения продукта.", "Оставлять щели между плитами или закрывать мокрый утеплитель."], "image": {"file": "wool.jpg", "alt": "Монтаж волокнистого утеплителя", "author": "Erik Mclean", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/unrecognizable-worker-insulating-with-stone-wool-6124239/", "download": "https://images.pexels.com/photos/6124239/pexels-photo-6124239.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "insulation.svg", "alt": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему.", "caption": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему."}, "videos": [{"title": "Утепление фасада: Дом за год", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "n_MstVbMNA0", "url": "https://www.youtube.com/watch?v=n_MstVbMNA0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Пожарная безопасность материалов: группы горючести';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Какие материалы лучше защищают от шума соседей.", "takeaways": ["Воздушный шум (голоса, музыка) гасится массой конструкции: чем тяжелее стена, тем лучше она изолирует звук.", "Лёгкие перегородки работают по принципу «масса — упругость — масса»: два слоя гипсокартона на отдельных каркасах и минеральная вата между ними.", "Газобетон и пенобетон из-за малой плотности изолируют звук хуже: перегородка из блоков D500 толщиной 100 мм — около 40–43 дБ."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Звукоизоляция перегородок и стен';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "insulation", "topic_name": "Утепление дома", "minutes": 2, "plain": "Из чего состоит навесной вентилируемый фасад.", "takeaways": ["Навесной вентилируемый фасад (НВФ) — система, в которой облицовка крепится на металлической подсистеме с воздушным зазором 40–60 мм от утеплителя.", "Слои системы: стена, кронштейны с терморазрывом, плиты минеральной ваты плотностью 80–100 кг/м³ (одним или двумя слоями), ветрогидрозащитная мембрана, воздушный зазор, направляющие, облицовка.", "Облицовкой служат керамогранит, фиброцементные панели, композитные кассеты, сайдинг, металлопрофиль."], "steps": ["Выберите материал, разрешённый для конкретной конструкции и нагрузки.", "Проверьте непрерывность утепления на откосах, цоколе и примыканиях.", "Защитите материал от намокания и проверьте крепление до закрытия слоя."], "mistakes": ["Сравнивать только плотность без назначения продукта.", "Оставлять щели между плитами или закрывать мокрый утеплитель."], "image": {"file": "wool.jpg", "alt": "Монтаж волокнистого утеплителя", "author": "Erik Mclean", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/unrecognizable-worker-insulating-with-stone-wool-6124239/", "download": "https://images.pexels.com/photos/6124239/pexels-photo-6124239.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "insulation.svg", "alt": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему.", "caption": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему."}, "videos": [{"title": "Утепление фасада: Дом за год", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "n_MstVbMNA0", "url": "https://www.youtube.com/watch?v=n_MstVbMNA0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Вентилируемый фасад: устройство';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "roof", "topic_name": "Кровля и мансарда", "minutes": 2, "plain": "Из каких материалов строят каркасный дом.", "takeaways": ["Каркасный дом строится из стоек и обвязок сечением 50×150 или 50×200 мм из сухой строганой древесины камерной сушки.", "Пирог стены изнутри наружу: внутренняя отделка (гипсокартон), пароизоляционная плёнка, каркас с минеральной ватой толщиной 150–200 мм, наружная обшивка OSB-3, ветрозащитная мембрана, вентзазор и фасадная отделка.", "Утеплитель — минеральная или стекловата плотностью 30–40 кг/м³."], "steps": ["Проверьте проектный состав кровли и назначение каждой плёнки.", "Герметично выполните внутренние примыкания и проходки.", "Сохраните предусмотренные вентиляционные зазоры и путь выхода воздуха."], "mistakes": ["Поменять местами пароизоляцию и диффузионную мембрану.", "Перекрыть выход воздуха утеплителем или отделкой."], "image": {"file": "roof.jpg", "alt": "Монтаж керамической кровельной черепицы", "author": "Clément Proust", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/installation-of-red-clay-roof-tiles-on-new-building-31771167/", "download": "https://images.pexels.com/photos/31771167/pexels-photo-31771167.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "roof.svg", "alt": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор.", "caption": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор."}, "videos": [{"title": "Теплоизоляция крыши: каменная вата и PIR", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "OcIOrGdhFG0", "url": "https://www.youtube.com/watch?v=OcIOrGdhFG0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Каркасный дом: материалы и пирог стены';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Пропорции и марки кладочного раствора.", "takeaways": ["Кладочный цементно-песчаный раствор готовят из цемента, песка и воды.", "Пропорции для цемента М400 (по объёму): М75 — 1 часть цемента на 4 части песка; М100 — 1:3; М150 — 1:2,5.", "Песок должен быть чистым, без глины, крупностью до 2,5 мм."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Строительный раствор для кладки кирпича';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Краткое содержание нормативов на керамический кирпич и камни.", "takeaways": ["ГОСТ 530-2012 «Кирпич и камень керамические.", "Стандарты определяют: номинальные размеры (одинарный кирпич 250×120×65 мм, полуторный 250×120×88 мм), допустимые отклонения, марки прочности М100–М300, марки морозостойкости F25–F100, классы средней плотности, водопоглощение (не менее 6 % для рядового кирпича и не более 14 % для лицевого).", "Также нормируются: наличие известковых включений, высолов, трещин и отбитостей."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "bricks.jpg", "alt": "Кирпичная кладка", "author": "Laura Tancredi", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/wall-made-of-rows-of-bricks-7078629/", "download": "https://images.pexels.com/photos/7078629/pexels-photo-7078629.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'ГОСТ 530-2012 и СТБ 1160-99: что регламентируют стандарты на кирпич';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Как отличить впитывающее основание от гладкого и подготовить стену без лишних слоёв.", "takeaways": ["Сначала проведите ладонью по стене: поверхность не должна осыпаться.", "На впитывающих минеральных поверхностях применяют совместимый грунт для регулирования впитывания.", "Проверьте технический лист будущей штукатурки, клея или краски: там указаны тип подготовки и ограничения."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [{"title": "Грунтование основания", "author": "Ceresit Беларусь", "provider": "YouTube", "youtube_id": "MlNJPxrzLdo", "url": "https://www.youtube.com/watch?v=MlNJPxrzLdo", "source": "https://www.ceresit.by/service/how-to/how-to-prime.html"}], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Грунтовка: какую выбрать и когда она действительно нужна';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Плитка и затирка не заменяют гидроизоляцию. Разбираем места, где чаще всего появляется протечка.", "takeaways": ["Начните с прочного ровного основания и заранее определите мокрые зоны, расположение слива и требуемые уклоны.", "Во внутренние углы и примыкания вклейте совместимую эластичную ленту, на выводы труб установите манжеты.", "Нанесите гидроизоляцию в предусмотренное изготовителем число слоёв."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [{"title": "Гидроизоляция под плиткой", "author": "Ceresit Беларусь", "provider": "YouTube", "youtube_id": "JwEucXTm9H0", "url": "https://www.youtube.com/watch?v=JwEucXTm9H0", "source": "https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html"}], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Гидроизоляция ванной: углы, трубы и порядок слоёв';
