INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "roof", "topic_name": "Кровля и мансарда", "minutes": 2, "plain": "Два похожих рулона выполняют разные задачи. Понятная схема утеплённой скатной кровли.", "takeaways": ["В типовой отапливаемой мансарде пароизоляционный слой располагают со стороны помещения, а диффузионную мембрану — снаружи утеплителя.", "Пароизоляция ограничивает поступление пара в утеплитель.", "Наружная мембрана защищает утеплитель от ветра и случайной воды и позволяет конструкции высыхать наружу."], "steps": ["Проверьте проектный состав кровли и назначение каждой плёнки.", "Герметично выполните внутренние примыкания и проходки.", "Сохраните предусмотренные вентиляционные зазоры и путь выхода воздуха."], "mistakes": ["Поменять местами пароизоляцию и диффузионную мембрану.", "Перекрыть выход воздуха утеплителем или отделкой."], "image": {"file": "roof.jpg", "alt": "Монтаж керамической кровельной черепицы", "author": "Clément Proust", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/installation-of-red-clay-roof-tiles-on-new-building-31771167/", "download": "https://images.pexels.com/photos/31771167/pexels-photo-31771167.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "roof.svg", "alt": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор.", "caption": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор."}, "videos": [{"title": "Теплоизоляция крыши: каменная вата и PIR", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "OcIOrGdhFG0", "url": "https://www.youtube.com/watch?v=OcIOrGdhFG0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Пароизоляция и мембрана: почему их нельзя менять местами';
