INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Разбираем маркировку клея и подбираем его по основанию, формату и условиям эксплуатации.", "takeaways": ["В распространённой классификации цементных клеёв C обозначает цементную основу, C1 — базовый уровень, C2 — улучшенные показатели сцепления.", "Более высокий класс не отменяет ограничений по основанию и формату.", "Клей наносят на подготовленное основание."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [{"title": "Укладка плитки из натурального камня", "author": "Ceresit Беларусь", "provider": "YouTube", "youtube_id": "Q-apGS9Gm2A", "url": "https://www.youtube.com/watch?v=Q-apGS9Gm2A", "source": "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-lay.html"}], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html", "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-lay.html"]}' FROM kb.Material WHERE title=N'Клей для плитки: что означаю