INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "water", "topic_name": "Влага и фундамент", "minutes": 2, "plain": "Как защитить молодой бетон от пересыхания и почему готовую смесь нельзя улучшать водой на глаз.", "takeaways": ["Прочность бетона зависит от состава, укладки, уплотнения и условий твердения.", "Сразу после отделки защитите поверхность от солнца, ветра и быстрого испарения.", "Не направляйте сильную струю на ещё слабую поверхность и не допускайте резкого охлаждения."], "steps": ["Определите источник воды и требования проекта к конструкции.", "Подготовьте основание, примыкания и проходки до основного покрытия.", "Проверьте сплошность защиты до обратной засыпки или закрытия отделкой."], "mistakes": ["Подменять гидроизоляцию обычным плиточным клеем.", "Нагружать свежий бетон по календарю без оценки набранной прочности."], "image": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "foundation.svg", "alt": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента.", "caption": "Защита подземной части: непрерывная гидроизоляция и предусмотренный проектом отвод воды. Схема не задаёт конструкцию фундамента."}, "videos": [], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Бетон после заливки: уход важнее добавления воды';
