INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "walls", "topic_name": "Стены и перегородки", "minutes": 2, "plain": "Каркас, заполнение, обшивка и примыкания: четыре части работающей системы.", "takeaways": ["Перегородка — это система из профилей, крепежа, заполнения и листов.", "На примыканиях каркаса к конструкциям используют предусмотренную системой уплотняющую ленту и герметизацию.", "Внутренние коммуникации размещают без повреждения стоек и листов."], "steps": ["Определите назначение стены: несущая, перегородка или облицовка.", "Сверьте геометрию, прочность и примыкания с проектом или альбомом системы.", "Проверьте первый ряд, перевязку, швы и качество каждого этапа до отделки."], "mistakes": ["Выбирать материал только по цене за штуку, не считая стену целиком.", "Менять крепёж, профили и элементы системы без проверки совместимости."], "image": {"file": "drywall.jpg", "alt": "Листы гипсокартона на складе", "author": "Pablo Fernandez", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/drywall-plasterboard-wallboard-27728636/", "download": "https://images.pexels.com/photos/27728636/pexels-photo-27728636.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "wall.svg", "alt": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект.", "caption": "Кладка из блоков: перевязка и ровность рядов. Схема условная, размеры и армирование задаёт проект."}, "videos": [{"title": "Монтаж перегородки КНАУФ С112", "author": "КНАУФ", "provider": "YouTube", "youtube_id": "APIEl1KPBQU", "url": "https://www.youtube.com/watch?v=APIEl1KPBQU", "source": "https://www.knauf.ru/"}, {"title": "Перегородка с однослойной обшивкой", "author": "КНАУФ", "provider": "YouTube", "youtube_id": "jFzgCJfkPuk", "url": "https://www.youtube.com/watch?v=jFzgCJfkPuk", "source": "https://www.knauf.ru/"}], "sources": ["https://www.knauf.ru/"]}' FROM kb.Material WHERE title=N'Гипсокартонная перегородка: что находится внутри';
