INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "garden", "topic_name": "Дорожки и участок", "minutes": 2, "plain": "Разделение слоёв, водоотвод и основание важнее красивого рисунка плитки.", "takeaways": ["Сначала определите нагрузку, грунт и путь отвода воды.", "Геотекстиль разделяет мелкий грунт и щебёночное основание, снижая перемешивание слоёв.", "Щебень укладывают и уплотняют послойно подходящим оборудованием."], "steps": ["Определите нагрузку и направление стока воды.", "Разделите грунт и основание подходящим геотекстилем, если он предусмотрен.", "Уплотняйте основание послойно и контролируйте уклон до укладки покрытия."], "mistakes": ["Уплотнять один толстый слой щебня вместо нескольких тонких.", "Направлять сток к дому или на соседний участок."], "image": {"file": "paving.svg", "alt": "Основание дорожки: покрытие, выравнивающий слой, уплотнённый щебень, разделение и грунт. Толщины зависят от нагрузки и грунта.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "paving.svg", "alt": "Основание дорожки: покрытие, выравнивающий слой, уплотнённый щебень, разделение и грунт. Толщины зависят от нагрузки и грунта.", "caption": "Основание дорожки: покрытие, выравнивающий слой, уплотнённый щебень, разделение и грунт. Толщины зависят от нагрузки и грунта."}, "videos": [], "sources": []}' FROM kb.Material WHERE title=N'Садовая дорожка: зачем геотекстиль и послойное уплотнение';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "insulation", "topic_name": "Утепление дома", "minutes": 2, "plain": "Оконные откосы, перемычки и пояса: почему одного значения толщины утеплителя недостаточно.", "takeaways": ["Тепловой мост возникает там, где тепло проходит легче, чем через соседние участки ограждения.", "Проблема проявляется не только в расходах на отопление.", "Непрерывность теплоизоляции проверяют на узлах: откосах, цоколе, примыканиях кровли и балконных плитах."], "steps": ["Выберите материал, разрешённый для конкретной конструкции и нагрузки.", "Проверьте непрерывность утепления на откосах, цоколе и примыканиях.", "Защитите материал от намокания и проверьте крепление до закрытия слоя."], "mistakes": ["Сравнивать только плотность без назначения продукта.", "Оставлять щели между плитами или закрывать мокрый утеплитель."], "image": {"file": "wool.jpg", "alt": "Монтаж волокнистого утеплителя", "author": "Erik Mclean", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/unrecognizable-worker-insulating-with-stone-wool-6124239/", "download": "https://images.pexels.com/photos/6124239/pexels-photo-6124239.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "insulation.svg", "alt": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему.", "caption": "Непрерывный слой утепления уменьшает тепловые мосты. Фасадные слои и крепления выбирают как одну систему."}, "videos": [{"title": "Утепление фасада: Дом за год", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "n_MstVbMNA0", "url": "https://www.youtube.com/watch?v=n_MstVbMNA0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Мостики холода: где дом теряет тепло';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "roof", "topic_name": "Кровля и мансарда", "minutes": 2, "plain": "Мягкий мат, фасадная плита и плита под стяжку не являются взаимозаменяемыми.", "takeaways": ["Для утепления важны теплопроводность в расчётных условиях, стабильность размеров, водопоглощение и механические свойства.", "В ненагруженной скатной кровле и каркасной стене используют изделия, предусмотренные для установки между элементами каркаса.", "Под стяжкой или кровельным ковром утеплитель воспринимает нагрузку."], "steps": ["Проверьте проектный состав кровли и назначение каждой плёнки.", "Герметично выполните внутренние примыкания и проходки.", "Сохраните предусмотренные вентиляционные зазоры и путь выхода воздуха."], "mistakes": ["Поменять местами пароизоляцию и диффузионную мембрану.", "Перекрыть выход воздуха утеплителем или отделкой."], "image": {"file": "roof.jpg", "alt": "Монтаж керамической кровельной черепицы", "author": "Clément Proust", "license": "Pexels License", "license_url": "https://www.pexels.com/license/", "source": "https://www.pexels.com/photo/installation-of-red-clay-roof-tiles-on-new-building-31771167/", "download": "https://images.pexels.com/photos/31771167/pexels-photo-31771167.jpeg?auto=compress&cs=tinysrgb&w=1200"}, "diagram": {"file": "roof.svg", "alt": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор.", "caption": "Условная схема утеплённой мансарды: пароизоляция внутри, утеплитель, наружная мембрана и вентилируемый зазор."}, "videos": [{"title": "Теплоизоляция крыши: каменная вата и PIR", "author": "ТЕХНОНИКОЛЬ", "provider": "YouTube", "youtube_id": "OcIOrGdhFG0", "url": "https://www.youtube.com/watch?v=OcIOrGdhFG0", "source": "https://www.tn.ru/"}], "sources": ["https://www.tn.ru/"]}' FROM kb.Material WHERE title=N'Минеральная вата: выбираем по назначению, а не только по плотности';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Усадка, слабое основание и подвижный стык требуют разных способов исправления.", "takeaways": ["Сначала определите, меняется ли трещина со временем и связана ли она с конструкцией.", "Тонкая сетка трещин может быть связана с быстрым высыханием, лишней водой или нарушением допустимой толщины слоя.", "На границе разных оснований может потребоваться специальное армирование или деформационное примыкание."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Штукатурка треснула: проверяем причину до ремонта';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Срок годности, целая упаковка и сухое хранение до начала ремонта.", "takeaways": ["Перед покупкой проверьте дату изготовления, срок хранения и целостность мешка.", "Храните мешки в сухом закрытом помещении на поддонах, отдельно от влажного пола и стен.", "Твёрдые комки, которые не рассыпаются, могут указывать на преждевременную гидратацию."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Хранение цемента и сухих смесей: как не купить испорченный мешок';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Пять пунктов, которые нужно проверить до покупки: назначение, основание, расход, время и ограничения.", "takeaways": ["Начните с назначения: внутри или снаружи, сухая или влажная зона, основание минеральное, деревянное или листовое.", "Найдите требования к основанию и подготовке: прочность, допустимую влажность, возраст, грунтование и минимальную температуру.", "Расход зависит от толщины, ровности и инструмента."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Как читать технический лист строительного материала';
GO

INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Даже морозостойкая плитка может отслоиться, если основание и клеевой слой удерживают воду.", "takeaways": ["Для наружной облицовки выбирают материал, разрешённый для улицы, с подходящей морозостойкостью и противоскольжением.", "Основание должно отводить воду.", "Клей и затирку подбирают для наружных условий и формата."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [{"title": "Укладка плитки из натурального камня", "author": "Ceresit Беларусь", "provider": "YouTube", "youtube_id": "Q-apGS9Gm2A", "url": "https://www.youtube.com/watch?v=Q-apGS9Gm2A", "source": "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-lay.html"}], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html", "https://www.ceresit.by/service/how-to/natural-stone-tiles-how-to-lay.html"]}' FROM kb.Material WHERE title=N'Плитка на улице: морозостойкость и вода под покрытием';
