INSERT kb.ArticleGuide(id_material,guide_json) SELECT id_material,N'{"topic": "finish", "topic_name": "Ремонт и отделка", "minutes": 2, "plain": "Понятный маршрут от обмера комнаты до закупки совместимых материалов.", "takeaways": ["Сформулируйте задачу: какое помещение, какие нагрузки, влажность и желаемое покрытие.", "Проверьте основание.", "Подбирайте совместимую систему: основание, грунт, выравнивающий слой, гидроизоляция при необходимости, клей или краска."], "steps": ["Проверьте прочность, ровность и влажность основания.", "Подберите совместимые грунт, выравнивание, защиту и финишное покрытие.", "Соблюдайте толщину слоёв и выдержки из технических листов."], "mistakes": ["Пытаться укрепить осыпающуюся стену одним слоем грунта.", "Путать время жизни раствора с открытым временем на стене."], "image": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "author": "Редакция ctroimir", "license": "Авторская учебная схема", "license_url": "http://dusovstroimir.mooo.com/about/", "source": "http://dusovstroimir.mooo.com/about/"}, "diagram": {"file": "finish.svg", "alt": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка.", "caption": "Под плиткой: прочное основание, подготовка, гидроизоляция в мокрой зоне, совместимый клей и облицовка."}, "videos": [], "sources": ["https://www.ceresit.by/service/how-to/how-to-make-waterproofing.html", "https://www.ceresit.by/service/how-to/how-to-prime.html"]}' FROM kb.Material WHERE title=N'Ремонт по шагам: что делать до покупки материалов';
